definition.raw:
Let $M \in \mathbb{N}$ and $\alpha, \beta > 0$. A function $\omega: [M]_0 \to \mathbb{R}$ satisfies the $(\alpha, \beta)$-decay condition if
\begin{align}
&\sum_{t = 0}^M \omega(t) = 0, \label{eqn:omega-balanced}\\
&\sum_{t = 0}^M |\omega(t)| = 1, \label{eqn:omega-norm}\\
&|\omega(t)| \le \alpha \exp (-\beta t) / t^2 \quad \forall t = 1, 2, \dots, M. \label{eqn:omega-decay}
\end{align}

we define $\mathcal{P}$ as the set of inputs for which every range item appears at most $T$ times, for a parameter $T$ to be chosen later:
\begin{equation}
    \mathcal{P}=\{x:\forall r\in [R],~\operatorname{\#}_r(x)\leq T\}.

define it as
\begin{equation}
    \mathcal{P}_\mathcal{R}=\{x:\forall r\in \mathcal{R},~\operatorname{\#}_r(x)\leq T\}.

Let $f : \{-1,1\}^m \to \{-1,1\}$ and $\psi : \{-1,1\}^m \to \mathbb{R}$ be functions such that
\begin{align} & \sum_{x \in E_+(\psi, f)} |\psi(x)| \le \delta^+ \label{eqn:deg-base-pos} \\
& \sum_{x \in E_-(\psi, f)} |\psi(x)| \le \delta^- \label{eqn:deg-base-neg} \\
& \|\psi\|_1 = 1 \label{eqn:deg-base-norm}
\end{align}
For every $M \in \mathbb{N}$ there exists a function $\rho : \{-1,1\}^M \to \mathbb{R}$ with $\|\rho\|_1 = 1$ and pure high degree $\Omega(\sqrt{M})$ such that
\begin{equation}
\langle \rho \star \psi, \mathsf{ OR}_M \circ f \rangle \ge \frac{9}{10} - 4  M \delta^+ - 4\delta^-.

Let $f : \{-1,1\}^N \to \{-1,1\}$ and let $\psi : \{-1,1\}^N \to \mathbb{R}$. We say that $\psi$ has one-sided error with respect to $f$ if for all $x \in \{-1,1\}^N$,
\begin{equation}
f(x) = 1 \implies \psi(x) > 0.
\end{equation}

theorem.raw:
\label{thm:main-reduction}
Let $f : \{-1,1\}^R \to \{-1,1\}$ be any function and let $g : \{-1,1\}^N \to \{-1,1\}$ be a symmetric function. Then for $F^{\operatorname{prop}}$ and $F^{\le N}$ defined above, and for any $\varepsilon > 0$, we have
\[\deg_\varepsilon(F^{\operatorname{prop}}) \ge \widetilde{\operatorname{ubdeg}}_\varepsilon(F^{\le N}).\]

\label{thm:dist}
For $k \ge 2$ and some $N = O_k(R)$, the $(1/3)$-approximate degree of $\mathsf{DIST}^k_{N, R}$ is $\tilde{\Omega}_k(R^{3/4 - 1/(2k)})$.
The same lower bound holds for the quantum query complexity of $\mathsf{DIST}^k_{N, R}$.

\label{sethm}
 For some constant $c > 0$, and any constant $\gamma \in (0, 1)$, $\widetilde{\operatorname{deg}}\left(\mathsf{ IST}_{N, R}^{\gamma}\right) \ge \tilde{\Omega}(R^{1/2})$, where $N = c \cdot \gamma^{-1/2} \cdot R$.
 The same lower bound applies to the quantum query complexity of $\mathsf{ IST}_{N, R}^{\gamma}$.

\label{thm:main-reductionpartial}
Let $Y \subset \{-1,1\}^R$ and let $f : Y \to \{-1,1\}$ be any partial function. Let $g : \{-1,1\}^N \to \{-1,1\}$ be any symmetric function. Then for $F^{\operatorname{prop}}$ and $F^{\le N}$ defined above, and for any $\varepsilon > 0$, we have
\[\widetilde{\operatorname{deg}}_\varepsilon(F^{\operatorname{prop}}) \ge \widetilde{\operatorname{dpdeg}}_\varepsilon(F^{\le N}).\]

\label{sduthm}
 For some $N = O(R)$, and some constants $0 < \gamma_2 < \gamma_1 < 1$, $\widetilde{\operatorname{deg}}\left(\mathsf{ SDU}_{N, R}^{\gamma_1, \gamma_2}\right) \ge \tilde{\Omega}(R^{1/2})$.
 The same lower bound applies to the quantum query complexity of $\mathsf{ SDU}_{N, R}^{\gamma_1, \gamma_2}$.

lemma.raw:
\label{andornor}
For any constant $\varepsilon \in (0, 1)$, the functions $\mathsf{AND}$ and $\mathsf{ OR}$ on $n$ bits have $\varepsilon$-approximate degree $\Theta(n^{1/2})$,
and the same holds for their negations.

\label{lem:inv-exp-tail}
Let $m \in \mathbb{N}$ and $\eta > 0$. Then
\[\sum_{r = m}^\infty e^{-\eta r} = \frac{1}{1 - e^{-\eta}} \cdot e^{-\eta m}.\]

\label{lem:cheb}
Let $d \in \mathbb{N}$.
\begin{enumerate}[(1)]
\item There exists a polynomial $T_d : \mathbb{R} \to \mathbb{R}$ (the Chebyshev polynomial of degree $d$) such that $T_d(x) \in [-1, 1]$ for all $x \in [-1, 1]$ and $T_d(1 + \mu) \ge \frac{1}{2} \exp(d\sqrt{\mu})$ for all $\mu \in (0, 1)$.
\item For any polynomial $p : \mathbb{R} \to \mathbb{R}$ of degree $d$ with $|p(x)| \le 1$ for all $x \in [-1, 1]$, we have that for any $x$ with $|x| > 1$,
\begin{equation}
    |p(x)| \leq |T_d(x)| \leq (2|x|)^d, \label{eq:swell}
\end{equation}
where $T_d$ is the Chebyshev polynomial of degree $d$.
\end{enumerate}

\label{lem:orT}
Let $\varepsilon \in (0, 1)$ and $1 \le T \le N$. There is a polynomial $V_{T, \varepsilon}:\{0,1\}^N\to \mathbb{R}$ of degree $O(\sqrt{T}\log (1/\varepsilon))$ such that
\begin{align}
V_{T, \varepsilon}(x) \in \begin{cases} [0,\varepsilon] &\mathrm{if}~ |x| = 0 \\
[1-\varepsilon,1] & \mathrm{if}~ 1\leq |x| \leq T \\ 
[-a, a] \text{ for some } a \in {\exp\left(O\left(\sqrt{T} \cdot \log N \cdot \log\left(1/\varepsilon\right)\right)\right)} & \mathrm{if}~ |x| > T \end{cases}.
\end{align}

\label{lem:real-bound}
Let $p : \mathbb{R}^n \to \mathbb{R}$ be a multilinear polynomial with $p(x) \in [0, 1]$ for all $x \in \{0,1\}^n$. Then for $x \in \mathbb{R}^n$, we have
\[|p(x)| \le \prod_{i = 1}^n (|1 - x_i| + |x_i|).\]

\label{lem:promiseSURJ} \label{lem:boundonprcal}
There exists a function $a(x) =  \exp\left(b_\mathcal{R}\left(x\right)\cdot \tilde{O}\left(\sqrt{T}\right)\right)$ such that for any $\mathcal{R} \subseteq [R]$, the polynomial $p_\mathcal{R}:[R]^N\to \mathbb{R}$ has degree $\tilde{O}(\sqrt{NT})$ and satisfies:
\begin{align*}
p_\mathcal{R}(x) \in \begin{cases} [0,1/10] &\mathrm{if}~ x\in\mathcal{P}_\mathcal{R} ~\mathrm{and}~ \mathsf{ SURJ}_\mathcal{R}(x)=0\\
[9/10,1] &\mathrm{if}~ x\in\mathcal{P}_\mathcal{R} ~\mathrm{and}~ \mathsf{ SURJ}_\mathcal{R}(x)=1\\
[-a(x), a(x)]& \mathrm{if}~ x \notin \mathcal{P}_\mathcal{R}.\end{cases}
\end{align*}

proposition.raw:
\label{prop:dumsurj-reduction}
Let $\varepsilon > 0$ and $N \ge R$. Then
\[ \widetilde{\operatorname{deg}}_\varepsilon(\mathsf{dSURJ}_{N, R}) \le \widetilde{\operatorname{deg}}_\varepsilon(\mathsf{ SURJ}_{N + 1, R + 1}) \cdot \log(R+1).\]

\label{prop:dumdist-reduction}
Let $\varepsilon > 0$, $N, R \in \mathbb{N}$, and $k \ge 2$. Then
\[ \deg_\varepsilon(\mathsf{dDIST}^k_{N, R}) \le \deg_\varepsilon(\mathsf{DIST}^k_{N, R+N}) \cdot \log(R+1).\]

\label{prop:ls}
The dual block composition satisfies the following properties:
\paragraph{\emph{Preservation of $\ell_1$-norm}:} If $\|\Psi\|_1 = 1$, $\|\psi\|_1 = 1$, and $\langle \psi, \mathbf{1}\rangle = 0$, then
\begin{equation}\|\Psi \star \psi\|_1 = 1. \label{eqn:ls-norm}\end{equation}

\paragraph{\emph{Multiplicativity of pure high degree}:} If $\langle \Psi, P \rangle = 0$ for every polynomial $P \colon \{-1,1\}^M \to \{-1,1\}$ of degree less than  $D$, and $\langle \psi, p \rangle = 0$ for every polynomial $p \colon \{-1,1\}^m \to \{-1,1\}$ of degree less than $d$, then
for every polynomial $q \colon \{-1,1\}^{m \cdot M} \to \{-1,1\}$,
\begin{equation}\deg q < D \cdot d \implies \langle \Psi \star \psi, q \rangle = 0. \label{eqn:ls-phd} \end{equation}

\paragraph{\emph{Associativity}:} For every $\zeta: \{-1,1\}^{m_\zeta} \to \mathbb{R}$, $\varphi: \{-1,1\}^{m_\varphi} \to \mathbb{R}$, and $\psi: \{-1,1\}^{m_\psi} \to \mathbb{R}$, we have
\begin{equation} (\zeta \star \varphi) \star \psi = \zeta \star (\varphi \star \psi). \label{eqn:ls-assoc} \end{equation}

\label{prop:prelim-mass}
Let $\Phi : \{-1,1\}^R \to \mathbb{R}$ and $\psi : \{-1,1\}^n \to \mathbb{R}$ satisfy the conditions of \Cref{prop:btzeroing}. Then for sufficiently large $R$, there exists $\Delta \ge \beta \sqrt{\alpha} R / 4\ln^2 R$ such that, for $N = \lceil 20 \sqrt{\alpha} \rceil R$,
\begin{equation}
\sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| \le (2NR)^{-2\Delta}. \label{eqn:prelim-mass}
\end{equation}

{adegsurj}, building on~\cite{razborovsherstov}}] \label{prop:correction}
Let $N \ge R > D$ and let $\xi : (\{-1,1\}^N)^R \to \mathbb{R}$ be any function such that
\[\sum_{x \notin H_{\le N}^{N \cdot R}} |\xi(x)| \le (2NR)^{-2D}.\]
Then there exists a function $\nu : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align*}
  &\text{For all polynomials } p \colon (\{-1,1\}^N)^R  \to \mathbb{R}\text{, } \deg p < D \implies \langle \nu, p \rangle = 0    \\
   &\|\nu\|_1 \le 1/10     \\
   &|x| > N \implies \nu(x) = \xi(x).    
\end{align*}

\label{prop:or-sym-dual}
Let $T \in \mathbb{N}$ and $1/T \le \delta \le 1/2$. There exist constants $c_1, c_2 \in (0, 1) $ and a function $\omega : [T]_0 \to \mathbb{R}$ such that
\begin{align}
&\omega(0) - \sum_{t = 1}^T \omega(t) \ge 1- \delta  \label{eqn:or-sym-corr}\\
&\sum_{t = 0}^T |\omega(t)| = 1 \\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:or-sym-phd}\\
& |\omega(t)| \le \frac{170 \exp(-c_2 t \sqrt{\delta} /  \sqrt{T})}{\delta \cdot t^2} \qquad \forall t = 1, \dots, T.\label{eqn:or-sym-decay}\end{align}

\label{prop:or-dual}
Let $T, N \in \mathbb{N}$ with $T \le N$, and let $\delta > 1/T$. Define $\omega$ as in \Cref{prop:or-sym-dual}. Define the function $\psi: \{-1,1\}^N \to \{-1,1\}$ by $\psi(x) = \omega(|x|) / \binom{N}{ |x|}$ for $x \in H^N_{\le T}$ and $\psi(x) = 0$ otherwise. Then
\begin{align} &\langle \psi, \mathsf{ OR}_N \rangle \ge 1-\delta  \label{eqn:or-corr} \\
& \|\psi\|_1 = 1   \label{eqn:or-norm}\\
& \text{For any polynomial } p \colon \{-1,1\}^N \to \mathbb{R}\text{, } \deg p < c_1\sqrt{\delta T} \implies \langle \psi, p \rangle = 0 \label{eqn:or-phd}
\end{align}

\label{prop:thr-sym-dual}
Let $k, T, N \in \mathbb{N}$ with $k \le T$. There exist constants $c_1, c_2 \in (0, 1] $ and a function $\omega : \{0, 1, \dots, T\} \to \mathbb{R}$ such that
\begin{align} & \sum_{\omega(t) > 0, t \ge k} |\omega(t)| \le \frac{1}{48N}  \label{eqn:thr-sym-pos-corr} \\
& \sum_{\omega(t) < 0, t < k} |\omega(t)| \le \left(\frac{1}{2} - \frac{2}{4^k}\right)\label{eqn:thr-sym-neg-corr} \\
& \|\omega\|_1 := \sum_{t = 0}^{T} |\omega(t)| = 1 \label{eqn:thr-sym-norm} \\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \notag \\
& \deg p < c_1\sqrt{k^{-1} \cdot T \cdot N^{-1/k}} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:thr-sym-phd} \\
&  |\omega(t)| \le \frac{(2k)^k \exp(-c_2 t / \sqrt{k \cdot T \cdot N^{1/k}})}{t^2} \qquad \forall t = 1, 2, \dots, T.\label{eqn:thr-sym-decay}
\end{align}

\label{prop:thr-dual}
Let $k, T, N\in \mathbb{N}$ with $k \le T \le N$. Define $\psi : \{-1,1\}^N \to \mathbb{R}$ by $\psi(x) = \omega(|x|) / \binom{N}{ |x|}$ for $x \in H_{\le T}^N$ and $\psi(x) = 0$ otherwise, where $\omega$ is as constructed in \Cref{prop:thr-sym-dual}. Then
\begin{align}
&\sum_{x \in E_+(\psi, \mathsf{THR}^k_N)} |\psi(x)| \le \frac{1}{48  N}  \label{eqn:thr-pos-corr}\\
&\sum_{x \in E_-(\psi, \mathsf{THR}^k_N)} |\psi(x)| \le \frac{1}{2} - \frac{2}{4^k}  \label{eqn:thr-neg-corr} \\
&\|\psi\|_1 = 1   \label{eqn:thr-norm} \\
&\text{For any polynomial } p \colon \{-1,1\}^N \to \mathbb{R}\text{, } \deg p < c_1 \sqrt{k^{-1} \cdot T \cdot N^{-1/k}} \implies \langle \psi, p \rangle = 0 \label{eqn:thr-phd} \\
&\sum_{|x| = t} |\psi(x)| \le (2k)^k \exp(-c_2 t / \sqrt{k \cdot T \cdot N^{1/k}})/t^2 \qquad \forall t = 1, 2, \dots, N.\label{eqn:thr-decay}
\end{align}

\label{prop:dist-prelim}
Let $k, T, N, R \in \mathbb{N}$ with $k \le T \le R \le N$ and $R$ divisible by $4^k$. Let $\psi : \{-1,1\}^N \to \mathbb{R}$ be a function with $\|\psi\|_1 = 1$ and
\begin{align*}
&\sum_{x \in E_+(\psi, \mathsf{THR}^k_N)} |\psi(x)| \le \frac{1}{48 N} \\
&\sum_{x \in E_-(\psi, \mathsf{THR}^k_N)} |\psi(x)| \le \frac{1}{2} - \frac{2}{4^k}. 
\end{align*}
Then there exists a function $\Phi : \{-1,1\}^R \to \mathbb{R}$ with $\|\Phi\|_1 = 1$ and pure high degree $\Omega(2^{-k} \sqrt{R})$ such that
\[ \langle \Phi \star \psi, \mathsf{ OR}_R \circ \mathsf{THR}^k_N \rangle \ge 2/3. \]

proof.raw:
To establish property (1), we use the fact that for $\mu > 0$, the value of the degree $d$ Chebyshev polynomial can be written~\cite[\S 3.2 Problem 8(f)]{cheney} 
 as
\begin{align*}
T_d(1 + \mu) &= \cosh ( d \operatorname{arcosh} ( 1 + \mu) ) \\
& \ge \cosh ( d \sqrt{\mu} ) & \text{ for } \mu \le 1\\
& \ge \frac{1}{2} \cdot \exp(d \sqrt{\mu}).
\end{align*}
Property (2) appears as~\cite[3.2 Problem 19]{cheney}.

\Cref{andornor} shows that the function $\mathsf{ OR}_M$ has $(9/10)$-approximate degree $\Omega(\sqrt{M})$. Hence, \Cref{prop:duality} guarantees the existence of a function $\rho : \{-1,1\}^M \to \mathbb{R}$ with $\|\rho\|_1 = 1$ and pure high degree $\Omega(\sqrt{M})$ such that
\begin{equation}
\langle \rho, \mathsf{ OR}_M \rangle \ge \frac{9}{10}.
\end{equation}
What remains is to establish the correlation bound~\eqref{eqn:deg-amp-corr}. Letting $\lambda$ denote the distribution $\lambda(x) = |\psi(x)|$ as in the proof of \Cref{prop:error-amp}, we may write
\begin{align}
& \sum_{(x_1, \dots, x_{M}) \in (\{-1,1\}^m)^M} (\varphi \star \psi) (x_1, \dots, x_M) \cdot \mathsf{ OR}_M(\dots, f(x_i), \dots) \nonumber \\
&\qquad= 2^{M} \mathbf{E}_{\lambda^{\otimes M}} [\varphi( \dots, \operatorname{sgn}(\psi(x_i)), \dots) \cdot \mathsf{ OR}_M\left( \dots, f(x_i), \dots\right)] \nonumber\\
&\qquad= \sum_{z \in \{-1,1\}^M} \varphi(z) \cdot \mathbf{E}_{\lambda^{\otimes M}} [\mathsf{ OR}_M(\dots, f(x_i), \dots) | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = z] \nonumber\\
&\qquad = \sum_{z \in \{-1,1\}^M} \varphi(z) \cdot \mathbf{E}_{y} [\mathsf{ OR}_M(\dots, y_i z_i, \dots)], \label{eqn:deg-amp-middle}
\end{align}
where $y \in \{-1,1\}^M$ is a random string whose $i$th bit independently takes the value $-1$ with probability $2 \sum_{x \in A_{z_i}} |\psi(x)|$. (Here, we are using the abbreviated notation $A_{+1} = E_+(\psi, f)$ and $A_{-1} = E_-(\psi, f)$.) We first consider the contribution of the term corresponding to $z = \mathbf{1}$ to the sum. Here, by a union bound,
\begin{align*}
\mathbf{E}_{y} [\mathsf{ OR}_M(\dots, y_i z_i, \dots)] &= 1 - 2 \Pr_y[\mathsf{ OR}_M(\dots, y_i, \dots) = -1] \\
&\ge 1 - 2 M \cdot \left(2 \sum_{x \in A_{+1}} |\psi(x)|\right) \\
&\ge 1 - 4 M\delta^+.
\end{align*}
Hence, the term $z = \mathbf{1}$ contributes $\varphi(\mathbf{1}) \cdot (1 - 4 M \delta^+)$ to the sum.

Now we consider the contribution of any term corresponding to $z \ne \mathbf{1}$. Given such a $z$, let $i^*$ be an index such that $z_{i^*} = -1$. Then we have
\begin{align*}
-\mathbf{E}_{y} [\mathsf{ OR}_M(\dots, y_i z_i, \dots)] &= 1 - 2 \Pr_y[\mathsf{ OR}_M(\dots, y_i z_i, \dots) = 1] \\
&\ge 1 - 2 \cdot \Pr_{y_{i^*}}[y_{i^*} = -1] \\
&= 1 - 2 \cdot \left(2 \sum_{x \in A_{-1}} |\psi(x)|\right) \\
&\ge 1 - 4 \delta^-.
\end{align*}

We can now lower bound~\eqref{eqn:deg-amp-middle} by
\begin{align*}\hspace{-1.1em}
\varphi(\mathbf{1}) \cdot (1 - 4 M \delta^+) - \sum_{z \ne \mathbf{1}} \varphi(z) (1 - 4\delta^-) &\ge \sum_{z \in \{-1,1\}^M} \varphi(z) \mathsf{ OR}_M(z) - 4M\delta^+ |\varphi(\mathbf{1})| - 4\delta^- \sum_{z \ne 1} |\varphi(z)| \\
&\ge \frac{9}{10} - 4M\delta^+ - 4\delta^-.\qedhere
\end{align*}

We begin by observing that the quantity of interest can be written as
\begin{align}
&\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - \nonumber \\
&\qquad\qquad \left( \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) + \sum_{x \in\{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)| \right) \nonumber \\
\ge &\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - 2 \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)|. \label{eqn:buttz}
\end{align}
We estimate each term of Expression~\eqref{eqn:buttz} separately, beginning with the first term. Just as in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we have
\begin{align*}
\sum_{x \in \{-1,1\}^{N \cdot R}} (\Phi \star \psi)(x) \cdot (\mathsf{AND}_R \circ \mathsf{ OR}_N)(x) &= \sum_{z \in \{-1,1\}^R} \Phi(z) \cdot \mathbb{E}_y[\mathsf{AND}_R(\dots, y_i z_i, \dots)]
\end{align*}
where $y \in \{-1,1\}^R$ is a random string whose $i$th bit independently takes the value $-1$ with probability $2 \sum_{x \in A_{z_i}} |\psi(x)|$. For $z = -\mathbf{1}$, we have by~\eqref{eqn:mybullshitequation} that $2 \sum_{x \in A_{-1}} |\psi(x)| = 0$, so the contribution of the corresponding term to the sum is $1/2$. For $z = \mathbf{1}$, we use the fact that $2 \sum_{x \in A_{+1}} |\psi(x)| \le \delta$ to compute
\begin{align*}
\frac{1}{2} \cdot \mathbb{E}_{y}[\mathsf{AND}_R(\dots, y_i, \dots)] &= \frac{1}{2} \cdot \left(1 - 2\Pr_y[\mathsf{AND}_R(\dots, y_i, \dots) = -1 ] \right) \\
&\ge \frac{1}{2} \cdot \left(1 - 2\delta^R\right).
\end{align*}
Hence, the first summand of~\eqref{eqn:buttz} is at least $1-\delta^R$.

We now estimate the second summand, $2 \sum_{x \notin G} |(\Phi \star \psi)(x)|$. As in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we let $\lambda$ denote the distribution with probability mass function $\lambda(x) = |\psi(x)|$. Then
\begin{align*}\hspace{-2.2em}
2\sum_{x \notin G} |(\Phi \star \psi)(x)| &= 2^{R+1} \mathbb{E}_{\lambda^{\otimes R}} [|\Phi(\dots, \operatorname{sgn} \psi(x_i), \dots)| \cdot \mathbb{I}(x \notin G)] \\
&= 2\sum_{z \in \{-1,1\}^R} |\Phi(z)| \cdot \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = z] \\
&= \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{-1}] + \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}].
\end{align*}
We analyze each term of this sum separately. For the first term, observe that by one-sided error of $\psi$, it follows that if $x = (x_1, \dots, x_R)$ is any input $\operatorname{sgn}(\psi(x_i)) = -1$ for all $i$ then $\mathsf{ OR}_N(x_i) = -1$ for all $i$. Thus we are guaranteed that $x \in G$, so the contribution of the first summand is zero. To analyze the second summand, let us denote by $r_i \in \{0, 1\}$ the indicator random variable for the event $\mathsf{ OR}_N(x_i) = -1$ when $x_i$ is drawn from the conditional distribution $(\lambda | \operatorname{sgn}(\psi(x_i)) = 1)$. Then
\begin{align*}
\Pr[r_i = 1] &= \Pr_{x_i \sim \lambda}[\mathsf{ OR}_N(x_i) = -1 | \operatorname{sgn}(\psi(x_i)) = 1] \\
&= 2\sum_{x \in A_{+1}} |\psi(x_i)| \\
&\le \delta
\end{align*}
by~\eqref{eqn:mybullshitequation}. Hence,
\begin{align*}
 \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}] &\le \Pr\left[ \sum_{i = 1}^R r_i  > \gamma R\right] \\
 &\le \exp\left(-\frac{(\gamma - \delta)R}{3}\right)
\end{align*}
by the multiplicative Chernoff bound.\footnote{The formulation we use here is as follows. Let $r_1, \dots, r_R$ be independent $\{0, 1\}$-valued random variables, $S = \sum_{i=1}^R r_i$, and $\mu = \mathbb{E}[S]$. Then for $\eta > 1$, we have $\Pr[S > (1+\eta) \mu] \le \exp(-\eta \mu / 3)$. In this application, we are taking $\mu \le \delta R$ and $\eta = \gamma R / \mu - 1 > 1$.} Thus, we have
\[2 \sum_{x \notin G} |(\Phi \star \psi)(x)| \le \exp\left(-\frac{(\gamma - \delta)R}{3}\right).\]
Putting everything together, we see that Expression~\eqref{eqn:buttz} is at least $1 - \delta^R - \exp\left(-(\gamma - \delta) R / 3\right)$ as we wanted to show.

algorithm.raw:
\caption{An informal description of the polynomial approximation for $\mathsf{ NOR}$}\label{alg:NOR}
\begin{algorithmic}[1]
\vspace{0.25em}
\State Using $q$, check if $|x|>T$ (with exponentially small probability of error if indeed $|x| > T$). If so, halt and output 0. 
\State Using $p$, compute $\mathsf{ NOR}$ under the promise that $0\leq |x| \leq T$ and output the result.
\end{algorithmic}

\caption{Informal description of the polynomial approximation for $\mathsf{ SURJ}$}\label{alg:SURJalmost}
\begin{algorithmic}[1]
\vspace{0.25em}
\State Sample $S=\tilde{\Theta}(N^{3/4})$ items and remove all range items seen from $[R]$. Let the remaining set be $\mathcal{R} \subseteq [R]$.
