Caricatures of these polynomials are depicted in \Cref{fig:p} and \Cref{fig:q}. It is now easy to see that the product $r(x)=p(x)\cdot q(x)$ is a (1/3)-error approximation to $\mathsf{ NOR}$ for $\emph{all}$ $x \in \{0,1\}^n$. 
The degree of the constructed polynomial is $\deg(r) \leq \deg(p) + \deg(q) = \tilde{O}(\sqrt{T}+\sqrt{n}) = \tilde{O}(\sqrt{n})$. 

Thus our constructed polynomial, $r$, has degree $\tilde{O}(\sqrt{n})$ and approximates $\mathsf{ NOR}$ to error $1/3$, which is optimal by \Cref{andornor}. 




\label{s:strategy}

Step 1: A Dual Witness for \texorpdfstring{$\mathsf{ OR
_N$}{OR}}


We begin by constructing a univariate function which captures the properties we need of our inner dual witness for $\mathsf{ OR}_N$. The construction slightly modifies the dual polynomial for $\mathsf{ OR}_N$ given by \v{S}palek \cite{spalek}. We provide a careful 
analysis of its decay as a function of the input's Hamming weight.

\begin{proposition} \label{prop:or-sym-dual}
Let $T \in \mathbb{N}$ and $1/T \le \delta \le 1/2$. There exist constants $c_1, c_2 \in (0, 1) $ and a function $\omega : [T]_0 \to \mathbb{R}$ such that
\begin{align}
&\omega(0) - \sum_{t = 1}^T \omega(t) \ge 1- \delta  \label{eqn:or-sym-corr}\\
&\sum_{t = 0}^T |\omega(t)| = 1 \\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:or-sym-phd}\\
& |\omega(t)| \le \frac{170 \exp(-c_2 t \sqrt{\delta} /  \sqrt{T})}{\delta \cdot t^2} \qquad \forall t = 1, \dots, T.\label{eqn:or-sym-decay}\end{align}
\end{proposition}


\begin{proof}[Proof of \Cref{prop:or-sym-dual}]
By renormalizing, it suffices to construction a function $\omega : [T]_0 \to \mathbb{R}$ such that
\begin{align} &\omega(0) - \sum_{t = 1}^T \omega(t) \ge (1 - \delta)\|\omega\|_1  \label{eqn:or-sym-corr-ref}\\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:or-sym-phd-ref}\\
& |\omega(t)| \le \frac{170 \exp(-c_2 t \sqrt{\delta} /\sqrt{T})\|\omega\|_1}{\delta \cdot t^2} \qquad \forall t = 1, \dots, T.\label{eqn:or-sym-decay-ref}\end{align}
 Let $c = \lceil 8 / \delta \rceil$ below. We will freely use the fact that since $\delta \le 1/2$, we have $c \le c^2 / (c-1) \le 10 /\delta$. Let $m = \lfloor \sqrt{T/2c} \rfloor$ and define the set
\[S = \{1, c\} \cup \{2ci^2 : 0 \le i \le m\}.\]
Note that $|S| \ge  c_1 \sqrt{\delta T}$ for some absolute constant $c_1 > 0$. Define the function
\[\omega(t) = \frac{(-1)^{t+(T-m)}}{T!} \binom{T}{t} \prod_{r \in [T]_0 \setminus S} (t - r).\]
Property~\eqref{eqn:or-sym-phd-ref} follows from the following well-known combinatorial identity.
\begin{fact}[e.g., \cite{concrete} Equation (5.23) or \cite{osnewbounds}] \label{fact:combinatorial}
Let $T \in \mathbb{N}$, and let $p$ be a polynomial of degree less than $T$. Then
\[\sum_{t = 0}^T (-1)^t \binom{T}{t} p(t) = 0.\]
\end{fact}

Expanding out the binomial coefficient in the definition of $\omega$ reveals that
\[|\omega(t)| = \begin{cases}
 \prod\limits_{r \in S \setminus \{t\}} \frac{1}{|t - r|} & \text{ for } t \in S, \\
0 & \text{ otherwise.}
\end{cases}\]

We now use this characterization to establish the improved tail decay property \eqref{eqn:or-sym-decay-ref}. This clearly holds for $t = 1$ with $c_2 = 1/10$, since $|\omega(1)| \le \|\omega\|_1$ and
\[\frac{170}{\delta} \exp(-c_2\sqrt{\delta} / \sqrt{T}) \ge 340 \cdot e^{-\sqrt{2} / 10} > 1.\]

For $t = c$, we have
\begin{align} \label{eqn:omega-2}
\frac{|\omega(c)|}{\omega(0)} &= \frac{c\prod_{i = 1}^m (2ci^2)}{c(c-1)\prod_{i = 1}^m (2ci^2 - c)} \nonumber \\
&= \frac{1}{c-1}\left(\prod_{i = 1}^m \frac{i^2 - 1/2}{i^2}\right)^{-1} \nonumber \\
&\le \frac{1}{c-1} \left(1 - \sum_{i=1}^m \frac{1}{2i^2}\right)^{-1} \nonumber \\
&\le \frac{1}{c-1} \left(1 - \frac{\pi^2}{12}\right)^{-1} \le \frac{6}{c - 1}
\end{align}
where the first inequality follows from the fact that $\prod_{i = 1}^m (1 - a_i) \ge 1 - \sum_{i = 1}^m a_i$ for $a_i \in (0, 1)$. Now note that
\begin{align*}
\frac{|\omega(c)|}{\|\omega\|_1} &\le \frac{|\omega(c)|}{\omega(0)} \\
&\le \frac{6}{c - 1} \\
&\le \frac{60}{\delta \cdot c^2} & \text{ since } 10/\delta \ge c^2 / (c-1) \\
& \le \frac{170}{\delta \cdot c^2} \cdot e^{-c\sqrt{\delta}/10\sqrt{T}},
\end{align*}
since $\delta \ge 1/T$ and hence $e^{-c\sqrt{\delta}/10\sqrt{T}} \ge e^{-1}$. Thus~\eqref{eqn:or-sym-decay-ref} holds for $t = c$, recalling that $c_2 = 1/10$.

For $t = 2cj^2$ with $j \ge 1$, we get
\begin{align*}
\frac{|\omega(t)|}{\omega(0)} &= \frac{c\prod_{i = 1}^m (2ci^2)}{(2cj^2 - 1)(2cj^2-c)\prod_{i \in [m]_0 \setminus \{j\}} |2ci^2 - 2cj^2|} \\
&= \frac{c(m!)^2}{(4c^2j^4 - (2c^2 + 2c)j^2 + c)\prod_{i \in [m]_0 \setminus \{j\}} (i+j)|i-j|} \\
&= \frac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \cdot \frac{(m!)^2}{(m+j)!(m-j)!}.
\end{align*}
For $j \ge 1$, the first factor is bounded by
\[\frac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \le \frac{3c}{(2cj^2)^2},\]
using the fact that $c \ge 2$. We control the second factor by
\begin{align*}
\frac{(m!)^2}{(m+j)!(m-j)!} &= \frac{m}{m+j} \cdot \frac{m-1}{m+j-1} \cdot \ldots \cdot \frac{m-j+1}{m+1} \\
&\le \left(\frac{m}{m+j} \right)^j \\
&\le  \left(1 - \frac{j}{2m} \right)^j \\
&\le e^{-j^2/2m},
\end{align*}
where the last inequality uses the fact that $1 - x \le e^{-x}$ for all $x$.
Since
\[\frac{|\omega(t)|}{\|\omega\|_1} \le \frac{|\omega(2cj^2)|}{\omega(0)} \le \frac{3c}{(2cj^2)^2} \cdot e^{-2cj^2/(4cm)} \le \frac{170}{\delta \cdot t^2} \cdot e^{-t \sqrt{\delta} / 10 \sqrt{T}},\]
this establishes~\eqref{eqn:or-sym-decay-ref}.


What remains is to perform the correlation calculation to establish~\eqref{eqn:or-sym-corr-ref}. For $t = 1$, we observe
\[\frac{|\omega(1)|}{\omega(0)} = \frac{c\prod_{i = 1}^m (2ci^2)}{(c-1)\prod_{i = 1}^m (2ci^2 - 1)} \ge \prod_{i=1}^m \frac{i^2}{i^2 - 1/(2c)} \ge 1.\]
Next, we observe that the total contribution of $t > c$ to $\|\omega\|_1/\omega(0)$ is at most
\begin{equation} \label{eqn:omega-tail}
\sum_{t > c} \frac{|\omega(t)|}{\omega(0)} \le \sum_{j=1}^{m} \frac{3c}{(2cj^2)^2} < \sum_{j=1}^\infty \frac{3}{4cj^4} = \frac{\pi^4}{120 c}.
\end{equation}


Next, we calculate
\begin{align}
\omega(0) - \sum_{t = 1}^T \omega(t) &\ge \omega(0) - \omega(1) - \left( \sum_{t = c}^T |\omega(t)|\right) \nonumber \\
&\ge \omega(0) - \omega(1) - \left( \omega(c) +  \omega(0) \cdot \frac{\pi^4}{120c}\right) & \text{by } \eqref{eqn:omega-tail} \nonumber \\
&\ge - \omega(1) + \omega(0) \left(1 - \frac{6}{c-1} - \frac{\pi^4}{120c}\right) & \text{by } \eqref{eqn:omega-2} \nonumber \\
&\ge - \omega(1)  + (1 - \delta)\omega(0) & \text{by our choice of } c \ge 8/\delta. \label{eqn:fudgethis}
\end{align}
On the other hand,
\begin{align}
\|\omega\|_1 &\le \omega(0) - \omega(1) + \omega(2) + \omega(0) \cdot \frac{\pi^4}{120c} & \text{by } \eqref{eqn:omega-tail} \nonumber \\
&\le -\omega(1) + \omega(0) \left(1 + \frac{6}{c - 1} + \frac{\pi^4}{120c} \right) &\text{by } \eqref{eqn:omega-2}\nonumber \\
&\le -\omega(1) + (1 + \delta)\omega(0) & \text{since } c \ge 8/\delta. \label{eqn:fudgethat}
\end{align}
Combining~\eqref{eqn:fudgethis} and~\eqref{eqn:fudgethat}, and using the fact that $-\omega(1) \ge \omega(0)$ shows that
\[\frac{\omega(0) - \sum_{t = 1}^k \omega(t)}{\|\omega\|_1} \ge \frac{-\omega(1) + (1-\delta) \omega(0)}{-\omega(1) + (1+\delta) \omega(0)} \ge \frac{2-\delta}{2 + \delta} \ge 1 - \delta.\]
This establishes~\eqref{eqn:or-sym-corr-ref}, completing the proof.
\end{proof}


The following construction of a dual polynomial for $\mathsf{ OR}_N$, with $N \ge T$, is an immediate consequence of Minsky-Papert symmetrization (\Cref{lem:mp}), combined with \Cref{prop:or-sym-dual}. 


\begin{proposition} \label{prop:or-dual}
Let $T, N \in \mathbb{N}$ with $T \le N$, and let $\delta > 1/T$. Define $\omega$ as in \Cref{prop:or-sym-dual}. Define the function $\psi: \{-1,1\}^N \to \{-1,1\}$ by $\psi(x) = \omega(|x|) / \binom{N}{ |x|}$ for $x \in H^N_{\le T}$ and $\psi(x) = 0$ otherwise. Then
\begin{align} &\langle \psi, \mathsf{ OR}_N \rangle \ge 1-\delta  \label{eqn:or-corr} \\
& \|\psi\|_1 = 1   \label{eqn:or-norm}\\
& \text{For any polynomial } p \colon \{-1,1\}^N \to \mathbb{R}\text{, } \deg p < c_1\sqrt{\delta T} \implies \langle \psi, p \rangle = 0 \label{eqn:or-phd}
\end{align}
\end{proposition}

Step 3: Constructing the Final Dual Witness
\label{sec:final-dual}

\label{sec:parametersetting} 


\begin{proposition} \label{prop:surj-dual}
Let $R$ be sufficiently large. There exist $N = O(R)$, $D = \tilde{\Omega}(N^{3/4})$, and  $\zeta : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align} \label{eq:surj-zero} &\zeta(x) = 0 \text{ for all } x \not\in H_{\le N}^{N \cdot R}, \\
\label{eq:surj-corr} &\sum_{x \in H_{\le N}^{N \cdot R}}\zeta(x) \cdot (\mathsf{AND}_{R} \circ \mathsf{ OR}_N)(x) > 1/3, \\
 \label{eq:surj-unitnorm} &\|\zeta\|_1 = 1, \text{ and }  \\
 \label{eq:surj-phd} &\text{ For every polynomial } p \colon (\{-1,1\}^N)^R\to \mathbb{R} \text{ of degree less than } D, \text{ we have } \langle p, \zeta \rangle = 0. 
\end{align}
\end{proposition}

\begin{proof}

We start by fixing choices of several key parameters:
\begin{itemize}
\item $d= \Theta(\sqrt{R})$ is the pure high degree of the dual witness $\Phi$ for $\mathsf{AND}_R$ in \Cref{prop:and-or},
\item $T = \lfloor(R/d)^{1/2}\rfloor^2 = \Theta(\sqrt{R})$,
\item $\hat{D} = c_1 \sqrt{T} \cdot d =\Theta(R^{3/4})$, where $c_1$ is the constant from \Cref{prop:or-sym-dual},
\item $\delta =1/20$
\item $\alpha = 170/\delta = 3400$,
\item $\beta = c_2 \cdot \sqrt{\delta} / \sqrt{T} = \Theta(1/R^{1/4})$, where $c_2$ is the constant from \Cref{prop:or-sym-dual},
\item $N = \lceil 20 \sqrt{\alpha} \rceil R = 693 R$.
\end{itemize}

Let $\psi : \{-1,1\}^N \to \{-1,1\}$ be the function constructed in \Cref{prop:or-dual} with $\delta:=1/20$. Let $\Phi : \{-1,1\}^R \to \{-1,1\}$ be the function constructed in \Cref{prop:and-or}, and define $\xi = \Phi \star \psi$. Then by \Cref{prop:ls}, $\xi$ satisfies the following properties:
\begin{align}& \langle \xi, \mathsf{AND}_R \circ \mathsf{ OR}_N \rangle > 2/3, \\
& \| \xi \|_1 = 1, \\ 
& \text{ For every polynomial } p \text{ of degree less than } D, \text{ we have }\langle \xi, p \rangle = 0. 
\end{align}
Recall that $\psi$ was obtained by symmetrizing the function $\omega$ constructed in \Cref{prop:or-sym-dual}.
\Cref{prop:btzeroing} guarantees that for some $\Delta \ge \beta \sqrt{\alpha} R / 4\ln^2 R = \tilde{\Omega}(R^{3/4})$, the function $\xi$ can be modified to produce a function $\zeta : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align*}
&\zeta(x) = 0 \text{ for all } x \not\in H_{\le N}^{N \cdot R}, \\
&\langle \zeta, \mathsf{AND}_R \circ \mathsf{ OR}_N \rangle \ge \langle \xi, \mathsf{AND}_R \circ \mathsf{ OR}_N \rangle - \|\zeta - \xi\|_1 \ge 2/3 - 2/9 > 1/3, \\
&\|\zeta\|_1 = 1, \\
& \text{ For every polynomial } p \text{ of degree less than } \min\{\hat{D}, \Delta\}, \text{ we have }\langle \zeta, p \rangle = 0. 
\end{align*}
Observing that
\[D =  \min\{\hat{D}, \Delta\} = \tilde{\Omega}(R^{3/4})\]
shows that the function $\zeta$ satisfies the conditions necessary to prove \Cref{prop:surj-dual}.
\end{proof}


\Cref{thm:main-amp} follows by combining \Cref{prop:surj-dual} with the dual characterization of unbounded approximate degree given in \Cref{prop:ub-duality}. By \Cref{cor:surj-reduction}, we conclude that $\widetilde{\operatorname{deg}}(\mathsf{dSURJ}_{N, R})=\tilde{\Omega}(R^{3/4})$. \Cref{thm:surj} follows by \Cref{prop:dumsurj-reduction}.

This is nearly tight for large $k$, as it approaches Belovs' upper bound of $O(n^{3/4-1/(2^{k + 2} - 4)})$. 
Note that both bounds approach $\Theta(n^{3/4})$ as $k\to \infty$.
It remains an intriguing open question to close the gap between $n^{3/4-1/(2^{k + 2} - 4)}$ and $n^{3/4-1/(2k)}$, especially for small values of $k \geq 3$. 

Our $k$-distinctness lower bound also implies an $\tilde{\Omega}(n^{3/4-1/(2k)})$ lower bound on the quantum query complexity of approximating the maximum frequency, $F_{\infty}$, of any element up to relative error less than $1/k$ \cite{montanaro}, improving over the previous best bound of $\tilde{\Omega}(n^{2/3})$. 



