\end{align}

Hence the $b\geq1$ term \eqref{eq:t2} is at most
\begin{align}
    \sum_{b=1}^{N/T} {\exp(-b \cdot \tilde{\Omega}(ST/N))} \cdot {\exp(b \cdot \tilde{O}(\sqrt{T}))} = o(1),
\end{align}
by choosing $T = \tilde{\Theta}(\sqrt{N})$ and $S = \tilde{\Theta}(N^{3/4})$ appropriately. This shows that the term in \eqref{eq:t2} does not significantly influence the value of the polynomial for any input $x$.

A Refinement of a Technical Lemma from Prior Work
The following technical proposition
 refines techniques of Bun and Thaler \cite{adegsurj}. 
This proposition is useful for ``zeroing out'' the mass that 
a dual polynomial $\xi$
places on inputs of high Hamming weight,
if $\xi$ is obtained via the dual-block method.


\begin{definition}
Let $M \in \mathbb{N}$ and $\alpha, \beta > 0$. A function $\omega: [M]_0 \to \mathbb{R}$ satisfies the $(\alpha, \beta)$-decay condition if
\begin{align}
&\sum_{t = 0}^M \omega(t) = 0, \label{eqn:omega-balanced}\\
&\sum_{t = 0}^M |\omega(t)| = 1, \label{eqn:omega-norm}\\
&|\omega(t)| \le \alpha \exp (-\beta t) / t^2 \quad \forall t = 1, 2, \dots, M. \label{eqn:omega-decay}
\end{align}
\end{definition}



\begin{restatable}{proposition}{btzeroing} \label{prop:btzeroing}
Let $R \in \mathbb{N}$ be sufficiently large, and let $\Phi : \{-1,1\}^R \to \mathbb{R}$ with $\|\Phi\|_1 = 1$. For $M \le R$, let $\omega : [M]_0 \to \mathbb{R}$ satisfy the $(\alpha, \beta)$-decay condition with parameters $1 \leq \alpha \le R^2, \beta \in (4\ln^2 R/ \sqrt{\alpha} R, 1)$.

Let $N = \lceil 20 \sqrt{\alpha} \rceil R$, and define $\psi: \{-1,1\}^N \to \mathbb{R}$ by $\psi(x) = \omega(|x|) / \binom{N}{|x|}$. If $D < N$ is such that
\begin{equation}
\text{ For every polynomial } p \text{ with } \deg p < D, \text{ we have } \langle \Phi \star \psi, p \rangle = 0, \label{eqn:prelim-phd}
\end{equation}
then there exist $\Delta \ge \beta\sqrt{\alpha} R / 4\ln^2 R$ and a function $\zeta: (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align}& \text{ For every polynomial } p \text{ with } \deg p < \min\{D, \Delta\}, \text{ we have } \langle \zeta, p \rangle = 0, \label{eqn:final-phd} \\
&\|\zeta - \Phi \star \psi\|_1 \le \frac{2}{9}, \label{eqn:final-corr} \\
&\|\zeta\|_1 = 1, \label{eqn:final-norm}\\
&\zeta \text{ is supported on } H^{N \cdot R}_{\le N}. \label{eqn:final-support}
\end{align}
\end{restatable}

The key refinement of \Cref{prop:btzeroing} relative to the analysis of Bun and Thaler
is that \Cref{prop:btzeroing} applies when $N=\Theta(R)$ (assuming $\alpha=O(1))$. In contrast, the techniques of Bun and Thaler required $N=\Omega(R \cdot \log^2 R)$. As indicated in \Cref{s:overviewoftheproofs}, this refinement will be essential in obtaining our lower bounds for $\mathsf{ SDU}$, entropy approximation, and junta testing for constant proximity parameter.

The proof of \Cref{prop:btzeroing} occurs in two steps. First, in \Cref{prop:prelim-mass}, we show that $\xi = \Phi \star \psi$ places an exponentially small amount of mass on inputs outside of $H_{\le N}^{N \cdot R}$. Second, in \Cref{prop:correction}, we construct a correction object $\nu$ that zeroes out the mass $\xi$ places outside of $H_{\le N}^{N \cdot R}$ without decreasing its pure high degree. Combining $\xi$ with $\nu$ yields the desired object $\zeta$.

\begin{proposition} \label{prop:prelim-mass}
Let $\Phi : \{-1,1\}^R \to \mathbb{R}$ and $\psi : \{-1,1\}^n \to \mathbb{R}$ satisfy the conditions of \Cref{prop:btzeroing}. Then for sufficiently large $R$, there exists $\Delta \ge \beta \sqrt{\alpha} R / 4\ln^2 R$ such that, for $N = \lceil 20 \sqrt{\alpha} \rceil R$,
\begin{equation}
\sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| \le (2NR)^{-2\Delta}. \label{eqn:prelim-mass}
\end{equation}
\end{proposition}


\begin{proof}
 Recall that $\psi(x) = \omega(|x|) / \binom{N}{|x|}$ where $\omega \colon [M]_{0} \to \mathbb{R}$. By Equation~\eqref{eqn:omega-balanced} we may write $\omega = \omega_{+1} - \omega_{-1}$  where $\omega_{+1}$ and $\omega_{-1}$ are non-negative
functions satisfying
\begin{equation} \label{eq:sweeteq} \sum_{t=0}^k \omega_{+1}(t) = \sum_{t=0}^k \omega_{-1}(t) = 1/2.\end{equation}



By the definition of dual block composition, we have
\[(\Phi \star \psi)(x_1, \dots, x_R) = 2^R \cdot \Phi(\dots, \operatorname{sgn}\left(\psi(x_i)\right), \dots) \cdot \prod_{i = 1}^R |\psi(x_i)|.\]
Consequently,
\begin{align}
\notag \sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| &= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{\substack{(x_1, \dots, x_R) \notin  H_{\le N}^{N \cdot R} \text{ s.t.} \\ \notag \operatorname{sgn}\left( \psi(x_1)\right) = z_1, \dots, \operatorname{sgn}\left(\psi(x_R)\right) = z_R}} \prod_{i = 1}^R |\psi(x_i)| \right) \\
&= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(x_1, \dots, x_R) \notin H_{\le N}^{N \cdot R}} \prod_{i = 1}^R \frac{\omega_{z_i}(|x_i|)}{\binom{N}{ |x_i|}} \right). \label{finallineman}
\end{align}

Observe that for any $(t_1, \dots, t_R) \in [M]_0^R$, the number of inputs $(x_1, \dots, x_R) \in \left(\{-1,1\}^N\right)^R$
such that $|x_i| = t_i$ for all $i \in [R]$ is exactly $\prod_{i=1}^{R} \binom{N}{ t_i}$. 
Hence, defining $$P = \{(t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\},$$ we
may rewrite Expression
\eqref{finallineman} as
\[2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(t_1, \dots, t_R) \in P} \prod_{i = 1}^R \omega_{z_i}(t_i) \right).\]
To control this quantity, we appeal to the following combinatorial lemma,
whose proof we delay to \Cref{s:proofofcomb} (this lemma
is a substantial refinement of \cite[Lemma 32]{adegsurj}).

\begin{restatable}{lemma}{combinatorial} \label{lem:combinatorial}
Let $\alpha \le R^2$, let $\beta \in (4\ln^2 R/ \sqrt{\alpha} R, 1)$, and let $R$ be sufficiently large. Let $N = \lceil 20 \sqrt{\alpha}\rceil R$. Let $\eta_i :[M]_0 \to \mathbb{R}$, for $i = 1, \dots R$, be a sequence of non-negative functions where for every $i$,
\begin{align}&\sum_{r = 0}^M \eta_i(r) \le 1 / 2     \label{eqn:eta-bound} \\
&\eta_i(r) \le \alpha \exp(-\beta r) / r^2  \qquad \forall r = 1, \dots, M.     \label{eqn:eta-decay} 
\end{align}
Let $P = \{\vec{t} = (t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\}$. Then
\[\sum_{\vec{t} \in P} \prod_{i = 1}^R  \eta_i(t_i) \le 2^{-R} \cdot (2NR)^{-2\Delta}\]
where $\Delta \ge \beta\sqrt{\alpha} R / 4\ln^2 R$.
\end{restatable}

Observe that the functions $\omega_{z_i}$ satisfy Condition \eqref{eqn:eta-bound} (cf. Equation \eqref{eq:sweeteq}) and Condition \eqref{eqn:eta-decay} (cf. Property~\eqref{eqn:omega-decay}). We complete the proof by bounding
\begin{align*}
2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{\vec{t} \in P} \prod_{i = 1}^R \omega_{z_i}(t_i) \right) &\le 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \cdot \left(2^{-R} \cdot (2NR)^{-2\Delta}\right)\\
&=(2NR)^{-2 \Delta} .
\end{align*}
Here, the equality appeals to the condition that $\|\Phi\|_1 = 1$.
\end{proof}


Our final dual witness $\zeta$ is obtained by modifying $\xi = \Phi \star \psi$ to zero out all of the mass it places on inputs of total Hamming weight larger than $N$. The following proposition captures the conditions under which this postprocessing step can be done. 


\begin{proposition}[{\cite[Proposition 34]{adegsurj}, building on~\cite{razborovsherstov}}] \label{prop:correction}
Let $N \ge R > D$ and let $\xi : (\{-1,1\}^N)^R \to \mathbb{R}$ be any function such that
\[\sum_{x \notin H_{\le N}^{N \cdot R}} |\xi(x)| \le (2NR)^{-2D}.\]
Then there exists a function $\nu : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align*}
  &\text{For all polynomials } p \colon (\{-1,1\}^N)^R  \to \mathbb{R}\text{, } \deg p < D \implies \langle \nu, p \rangle = 0    \\
   &\|\nu\|_1 \le 1/10     \\
   &|x| > N \implies \nu(x) = \xi(x).    
\end{align*}
\end{proposition}

\begin{remark}
\Cref{prop:correction} is framed exclusively in the language 
of dual polynomials: it states that if a dual polynomial $\xi$ places very little mass on inputs
of Hamming weight more than $N$,
then there exists another dual polynomial $\nu$ satisfying certain useful properties
(we ultimately use $\nu$ to zero out the mass that $\xi$ places on inputs of Hamming weight more than $N$).
\Cref{prop:correction} also has a clean \emph{primal} formulation. Roughly speaking,
it is equivalent to a bound on the growth rate of any polynomial of degree at most $D$ that is bounded at
all inputs of Hamming weight at most $D$. We direct the interested
reader to \cite{violalecturenotes} for details of this primal formulation.
\end{remark}



We are now ready to combine \Cref{prop:prelim-mass} and \Cref{prop:correction} to complete the proof of \Cref{prop:btzeroing}.

\begin{proof}[Proof of \Cref{prop:btzeroing}]
Let $\xi = \Phi \star \psi$. By \Cref{prop:prelim-mass}, we have
\[\sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| \le (2 N R)^{-2\Delta},\]
where $\Delta \ge \beta \sqrt{\alpha} R /\ln^2 R$. By \Cref{prop:correction}, there exists a function $\nu : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align}
  &\text{For all polynomials } p \colon (\{-1,1\}^N)^R  \to \mathbb{R}\text{, } \deg p < \min\{D, \Delta\} \implies \langle \nu, p \rangle = 0    \label{eqn:correction-phd} \\
   &\|\nu\|_1 \le 1/10     \label{eqn:correction-norm}  \\
   &|x| > N \implies \nu(x) = \xi(x).     \label{eqn:correction-correct}  
\end{align}


Observe that $\|\xi - \nu\|_1 > 0$, as
$\|\xi\|_1 = 1$ (cf. Equation \eqref{eqn:ls-norm}) and $\|\nu\|_1 \leq 1/10$ (cf. Inequality \eqref{eqn:correction-norm}).
Define the function
\[\zeta(x) = \frac{\xi(x) - \nu(x)}{\|\xi - \nu\|_1}.\]
Since $\nu(x) = \xi(x)$ whenever $|x| > N$ (cf. Equation~\eqref{eqn:correction-correct}), the function $\zeta$ is supported on the set $H_{\le N}^{N \cdot R}$, establishing~\eqref{eqn:final-support}. We establish~\eqref{eqn:final-corr} by computing
\begin{align*}
\|\zeta - \xi\|_1 &= \sum_{x \in (\{-1,1\}^N)^R} \left|  \frac{\xi(x) - \nu(x)}{\|\xi - \nu\|_1} - \xi(x)\right| \\
&\le \sum_{x \in (\{-1,1\}^N)^R} \left( \frac{1}{\|\xi - \nu\|_1} - 1\right)|\xi(x)| + \frac{1}{\|\xi - \nu\|_1}|\nu(x)| \\
&\le \left( \frac{1}{\|\xi\|_1 - \|\nu\|_1} - 1 \right) \cdot \|\xi\|_1 + \frac{1}{\|\xi\|_1 - \|\nu\|_1} \cdot \|\nu\|_1 \\
&\le \left(\frac{1}{1 - 1/10} - 1 \right)+ \frac{1 /10 }{1 - 1/10} \\
&= \frac{2}{9}.
\end{align*}

Equation~\eqref{eqn:final-norm} is immediate from the definition of $\zeta$. Finally,~\eqref{eqn:final-phd} follows from~\eqref{eqn:prelim-phd}, \eqref{eqn:correction-phd}, and linearity.
\end{proof}

Step 1: A Dual Witness for \texorpdfstring{$\mathsf{ OR
_N$}{OR}}


We begin by constructing a univariate function which captures the properties we need of our inner dual witness for $\mathsf{ OR}_N$. The construction slightly modifies the dual polynomial for $\mathsf{ OR}_N$ given by \v{S}palek \cite{spalek}. We provide a careful 
analysis of its decay as a function of the input's Hamming weight.

\begin{proposition} \label{prop:or-sym-dual}
Let $T \in \mathbb{N}$ and $1/T \le \delta \le 1/2$. There exist constants $c_1, c_2 \in (0, 1) $ and a function $\omega : [T]_0 \to \mathbb{R}$ such that
\begin{align}
&\omega(0) - \sum_{t = 1}^T \omega(t) \ge 1- \delta  \label{eqn:or-sym-corr}\\
&\sum_{t = 0}^T |\omega(t)| = 1 \\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:or-sym-phd}\\
& |\omega(t)| \le \frac{170 \exp(-c_2 t \sqrt{\delta} /  \sqrt{T})}{\delta \cdot t^2} \qquad \forall t = 1, \dots, T.\label{eqn:or-sym-decay}\end{align}
\end{proposition}


\begin{proof}[Proof of \Cref{prop:or-sym-dual}]
By renormalizing, it suffices to construction a function $\omega : [T]_0 \to \mathbb{R}$ such that
\begin{align} &\omega(0) - \sum_{t = 1}^T \omega(t) \ge (1 - \delta)\|\omega\|_1  \label{eqn:or-sym-corr-ref}\\
& \text{For all univariate polynomials } q \colon \mathbb{R} \to \mathbb{R}\text{, } \deg q < c_1\sqrt{\delta T} \implies \sum_{t=0}^T \omega(t) \cdot q(t) = 0 \label{eqn:or-sym-phd-ref}\\
& |\omega(t)| \le \frac{170 \exp(-c_2 t \sqrt{\delta} /\sqrt{T})\|\omega\|_1}{\delta \cdot t^2} \qquad \forall t = 1, \dots, T.\label{eqn:or-sym-decay-ref}\end{align}
 Let $c = \lceil 8 / \delta \rceil$ below. We will freely use the fact that since $\delta \le 1/2$, we have $c \le c^2 / (c-1) \le 10 /\delta$. Let $m = \lfloor \sqrt{T/2c} \rfloor$ and define the set
\[S = \{1, c\} \cup \{2ci^2 : 0 \le i \le m\}.\]
Note that $|S| \ge  c_1 \sqrt{\delta T}$ for some absolute constant $c_1 > 0$. Define the function
\[\omega(t) = \frac{(-1)^{t+(T-m)}}{T!} \binom{T}{t} \prod_{r \in [T]_0 \setminus S} (t - r).\]
Property~\eqref{eqn:or-sym-phd-ref} follows from the following well-known combinatorial identity.
\begin{fact}[e.g., \cite{concrete} Equation (5.23) or \cite{osnewbounds}] \label{fact:combinatorial}
Let $T \in \mathbb{N}$, and let $p$ be a polynomial of degree less than $T$. Then
\[\sum_{t = 0}^T (-1)^t \binom{T}{t} p(t) = 0.\]
\end{fact}

Expanding out the binomial coefficient in the definition of $\omega$ reveals that
\[|\omega(t)| = \begin{cases}
 \prod\limits_{r \in S \setminus \{t\}} \frac{1}{|t - r|} & \text{ for } t \in S, \\
0 & \text{ otherwise.}
\end{cases}\]

We now use this characterization to establish the improved tail decay property \eqref{eqn:or-sym-decay-ref}. This clearly holds for $t = 1$ with $c_2 = 1/10$, since $|\omega(1)| \le \|\omega\|_1$ and
\[\frac{170}{\delta} \exp(-c_2\sqrt{\delta} / \sqrt{T}) \ge 340 \cdot e^{-\sqrt{2} / 10} > 1.\]

For $t = c$, we have
\begin{align} \label{eqn:omega-2}
\frac{|\omega(c)|}{\omega(0)} &= \frac{c\prod_{i = 1}^m (2ci^2)}{c(c-1)\prod_{i = 1}^m (2ci^2 - c)} \nonumber \\
&= \frac{1}{c-1}\left(\prod_{i = 1}^m \frac{i^2 - 1/2}{i^2}\right)^{-1} \nonumber \\
&\le \frac{1}{c-1} \left(1 - \sum_{i=1}^m \frac{1}{2i^2}\right)^{-1} \nonumber \\
&\le \frac{1}{c-1} \left(1 - \frac{\pi^2}{12}\right)^{-1} \le \frac{6}{c - 1}
\end{align}
where the first inequality follows from the fact that $\prod_{i = 1}^m (1 - a_i) \ge 1 - \sum_{i = 1}^m a_i$ for $a_i \in (0, 1)$. Now note that
\begin{align*}
\frac{|\omega(c)|}{\|\omega\|_1} &\le \frac{|\omega(c)|}{\omega(0)} \\
&\le \frac{6}{c - 1} \\
&\le \frac{60}{\delta \cdot c^2} & \text{ since } 10/\delta \ge c^2 / (c-1) \\
& \le \frac{170}{\delta \cdot c^2} \cdot e^{-c\sqrt{\delta}/10\sqrt{T}},
\end{align*}
since $\delta \ge 1/T$ and hence $e^{-c\sqrt{\delta}/10\sqrt{T}} \ge e^{-1}$. Thus~\eqref{eqn:or-sym-decay-ref} holds for $t = c$, recalling that $c_2 = 1/10$.

For $t = 2cj^2$ with $j \ge 1$, we get
\begin{align*}
\frac{|\omega(t)|}{\omega(0)} &= \frac{c\prod_{i = 1}^m (2ci^2)}{(2cj^2 - 1)(2cj^2-c)\prod_{i \in [m]_0 \setminus \{j\}} |2ci^2 - 2cj^2|} \\
&= \frac{c(m!)^2}{(4c^2j^4 - (2c^2 + 2c)j^2 + c)\prod_{i \in [m]_0 \setminus \{j\}} (i+j)|i-j|} \\
&= \frac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \cdot \frac{(m!)^2}{(m+j)!(m-j)!}.
\end{align*}
For $j \ge 1$, the first factor is bounded by
\[\frac{c}{4c^2j^4 - (2c^2 + 2c)j^2 + c} \le \frac{3c}{(2cj^2)^2},\]
using the fact that $c \ge 2$. We control the second factor by
\begin{align*}
\frac{(m!)^2}{(m+j)!(m-j)!} &= \frac{m}{m+j} \cdot \frac{m-1}{m+j-1} \cdot \ldots \cdot \frac{m-j+1}{m+1} \\
&\le \left(\frac{m}{m+j} \right)^j \\
&\le  \left(1 - \frac{j}{2m} \right)^j \\
&\le e^{-j^2/2m},
\end{align*}
where the last inequality uses the fact that $1 - x \le e^{-x}$ for all $x$.
Since
\[\frac{|\omega(t)|}{\|\omega\|_1} \le \frac{|\omega(2cj^2)|}{\omega(0)} \le \frac{3c}{(2cj^2)^2} \cdot e^{-2cj^2/(4cm)} \le \frac{170}{\delta \cdot t^2} \cdot e^{-t \sqrt{\delta} / 10 \sqrt{T}},\]
this establishes~\eqref{eqn:or-sym-decay-ref}.


What remains is to perform the correlation calculation to establish~\eqref{eqn:or-sym-corr-ref}. For $t = 1$, we observe
\[\frac{|\omega(1)|}{\omega(0)} = \frac{c\prod_{i = 1}^m (2ci^2)}{(c-1)\prod_{i = 1}^m (2ci^2 - 1)} \ge \prod_{i=1}^m \frac{i^2}{i^2 - 1/(2c)} \ge 1.\]
Next, we observe that the total contribution of $t > c$ to $\|\omega\|_1/\omega(0)$ is at most
\begin{equation} \label{eqn:omega-tail}
\sum_{t > c} \frac{|\omega(t)|}{\omega(0)} \le \sum_{j=1}^{m} \frac{3c}{(2cj^2)^2} < \sum_{j=1}^\infty \frac{3}{4cj^4} = \frac{\pi^4}{120 c}.
\end{equation}


Next, we calculate
\begin{align}
\omega(0) - \sum_{t = 1}^T \omega(t) &\ge \omega(0) - \omega(1) - \left( \sum_{t = c}^T |\omega(t)|\right) \nonumber \\
&\ge \omega(0) - \omega(1) - \left( \omega(c) +  \omega(0) \cdot \frac{\pi^4}{120c}\right) & \text{by } \eqref{eqn:omega-tail} \nonumber \\
&\ge - \omega(1) + \omega(0) \left(1 - \frac{6}{c-1} - \frac{\pi^4}{120c}\right) & \text{by } \eqref{eqn:omega-2} \nonumber \\
&\ge - \omega(1)  + (1 - \delta)\omega(0) & \text{by our choice of } c \ge 8/\delta. \label{eqn:fudgethis}
\end{align}
On the other hand,
\begin{align}
\|\omega\|_1 &\le \omega(0) - \omega(1) + \omega(2) + \omega(0) \cdot \frac{\pi^4}{120c} & \text{by } \eqref{eqn:omega-tail} \nonumber \\
&\le -\omega(1) + \omega(0) \left(1 + \frac{6}{c - 1} + \frac{\pi^4}{120c} \right) &\text{by } \eqref{eqn:omega-2}\nonumber \\
&\le -\omega(1) + (1 + \delta)\omega(0) & \text{since } c \ge 8/\delta. \label{eqn:fudgethat}
\end{align}
Combining~\eqref{eqn:fudgethis} and~\eqref{eqn:fudgethat}, and using the fact that $-\omega(1) \ge \omega(0)$ shows that
\[\frac{\omega(0) - \sum_{t = 1}^k \omega(t)}{\|\omega\|_1} \ge \frac{-\omega(1) + (1-\delta) \omega(0)}{-\omega(1) + (1+\delta) \omega(0)} \ge \frac{2-\delta}{2 + \delta} \ge 1 - \delta.\]
This establishes~\eqref{eqn:or-sym-corr-ref}, completing the proof.
\end{proof}


The following construction of a dual polynomial for $\mathsf{ OR}_N$, with $N \ge T$, is an immediate consequence of Minsky-Papert symmetrization (\Cref{lem:mp}), combined with \Cref{prop:or-sym-dual}. 


\begin{proposition} \label{prop:or-dual}
Let $T, N \in \mathbb{N}$ with $T \le N$, and let $\delta > 1/T$. Define $\omega$ as in \Cref{prop:or-sym-dual}. Define the function $\psi: \{-1,1\}^N \to \{-1,1\}$ by $\psi(x) = \omega(|x|) / \binom{N}{ |x|}$ for $x \in H^N_{\le T}$ and $\psi(x) = 0$ otherwise. Then
\begin{align} &\langle \psi, \mathsf{ OR}_N \rangle \ge 1-\delta  \label{eqn:or-corr} \\
& \|\psi\|_1 = 1   \label{eqn:or-norm}\\
& \text{For any polynomial } p \colon \{-1,1\}^N \to \mathbb{R}\text{, } \deg p < c_1\sqrt{\delta T} \implies \langle \psi, p \rangle = 0 \label{eqn:or-phd}
\end{align}
\end{proposition}

Step 3: Constructing the Final Dual Witness
\label{sec:final-dual}

\label{sec:parametersetting} 


\begin{proposition} \label{prop:surj-dual}
Let $R$ be sufficiently large. There exist $N = O(R)$, $D = \tilde{\Omega}(N^{3/4})$, and  $\zeta : (\{-1,1\}^N)^R \to \mathbb{R}$ such that
\begin{align} \label{eq:surj-zero} &\zeta(x) = 0 \text{ for all } x \not\in H_{\le N}^{N \cdot R}, \\
\label{eq:surj-corr} &\sum_{x \in H_{\le N}^{N \cdot R}}\zeta(x) \cdot (\mathsf{AND}_{R} \circ \mathsf{ OR}_N)(x) > 1/3, \\
 \label{eq:surj-unitnorm} &\|\zeta\|_1 = 1, \text{ and }  \\
 \label{eq:surj-phd} &\text{ For every polynomial } p \colon (\{-1,1\}^N)^R\to \mathbb{R} \text{ of degree less than } D, \text{ we have } \langle p, \zeta \rangle = 0. 
\end{align}
\end{proposition}

\begin{proof}

We start by fixing choices of several key parameters:
\begin{itemize}
\item $d= \Theta(\sqrt{R})$ is the pure high degree of the dual witness $\Phi$ for $\mathsf{AND}_R$ in \Cref{prop:and-or},
\item $T = \lfloor(R/d)^{1/2}\rfloor^2 = \Theta(\sqrt{R})$,
\item $\hat{D} = c_1 \sqrt{T} \cdot d =\Theta(R^{3/4})$, where $c_1$ is the constant from \Cref{prop:or-sym-dual},
\item $\delta =1/20$
\item $\alpha = 170/\delta = 3400$,
\item $\beta = c_2 \cdot \sqrt{\delta} / \sqrt{T} = \Theta(1/R^{1/4})$, where $c_2$ is the constant from \Cref{prop:or-sym-dual},
\item $N = \lceil 20 \sqrt{\alpha} \rceil R = 693 R$.
\end{itemize}

Let $\psi : \{-1,1\}^N \to \{-1,1\}$ be the function constructed in \Cref{prop:or-dual} with $\delta:=1/20$. Let $\Phi : \{-1,1\}^R \to \{-1,1\}$ be the function constructed in \Cref{prop:and-or}, and define $\xi = \Phi \star \psi$. Then by \Cref{prop:ls}, $\xi$ satisfies the following properties:
\begin{align}& \langle \xi, \mathsf{AND}_R \circ \mathsf{ OR}_N \rangle > 2/3, \\
& \| \xi \|_1 = 1, \\ 
& \text{ For every polynomial } p \text{ of degree less than } D, \text{ we have }\langle \xi, p \rangle = 0. 
\end{align}
Recall that $\psi$ was obtained by symmetrizing the function $\omega$ constructed in \Cref{prop:or-sym-dual}.
