\begin{lemma} \label{lem:inv-sqrt}
Let $m \in N$. Then
\[\sum_{r = 1}^m \frac{1}{\sqrt{r}} \le 2 \sqrt{m}.\]
\end{lemma}

\begin{proof}
Using the fact that the function $1/\sqrt{t}$ is decreasing, we may estimate
\[
  \sum_{r = 1}^m \frac{1}{\sqrt{r}} \le \int_{0}^m \frac{1}{\sqrt{t}} \ dt = 2\sqrt{m}.\qedhere
\]
\end{proof}

\begin{proof}

Let $T = \lfloor \frac{N}{2M} \rfloor$.  For each $s \in \{T, \dots, R\}$, let 
\[C(s) = \max \left\{ \frac{N}{6 s \ln R}, \frac{N}{6\sqrt{R \cdot s}} \right\}.\]

We begin with a simple, but important, structural observation about the set $P$. Let $t = (t_1, \dots, t_R) \in [M]_0^R$ be a sequence such that $t_1 + \dots + t_R > N$. Then  we claim that there exists an $s \in \{T \dots, R\}$ such that $t_i \ge C(s)$ for at least $s$ indices $i \in [R]$. To see this, assume without loss of generality that the entries of $\vec{t}$ are sorted so that $t_1 \ge t_2 \ge \dots \ge t_R$. Then there must exist an $s \geq T$ such that $t_s \ge C(s)$. Otherwise, because no $t_i$ can exceed $M$, we would have:
\begin{align*}
t_1 + \dots + t_R  &< T \cdot M + \sum_{s = 1}^R C(s) \\
&\le \frac{N}{2} + \frac{N}{6 \ln R} \sum_{s = 1}^{\lfloor R / \ln^2 R \rfloor} \frac{1}{s} + \frac{N}{6\sqrt{R}} \sum_{s = \lceil R / \ln^2 R \rceil}^R \frac{1}{\sqrt{s}}\\
&\le \frac{N}{2}+ \frac{N}{6} + \frac{N}{3} \\
&= N.
\end{align*}
where the last inequality follows from \Cref{lem:inv-sqrt} and the fact that $\sum_{s = 1}^m s^{-1} \le \ln m + 1$ (and $R$ is sufficiently large). 
Since the entries of $\vec{t}$ are sorted, the preceding values $t_1, \dots, t_{s-1} \geq C(s)$ as well. 



For each subset $S \subseteq [R]$, define
\[P_S = \{\vec{t} \in P : t_i \ge C(|S|)\text{ for all indices }i \in S\}.\]
The observations above guarantee that for every $\vec{t}=(t_1, \dots, t_R) \in P$, 
there exists some set $S$ of size at least $s \in \{T, \dots, R\}$ such that 
$t_i \geq C(s)$ for all $i \in S$. Hence
\begin{align*} \hspace{-10mm}
\sum_{\vec{t} \in P} \prod_{i = 1}^R \eta_i(t_i)  & \leq \sum_{s = T}^{R} \sum_{S \subseteq [R] : |S| = s} \sum_{\vec{t} \in P_S} \prod_{i = 1}^R \eta_i(t_i) \\
& \leq \sum_{s = T}^{R} \binom{R}{s} \left( \max_{i \in \{1, \dots, R\}} \left( \sum_{r=\lceil C(s) \rceil}^M \eta_i(r)\right) \right)^s  \left( \max_{i \in \{1, \dots, R\}} \left( \sum_{r = 0}^M \eta_i(r) \right)\right)^{R-s} \hspace{-3.3em}&\hspace{-3em}\\
&\leq  2^{-R}\sum_{s = T}^{R} \binom{R}{s} \left( \sum_{r = \lceil C(s) \rceil}^M 2\alpha \exp(-\beta r ) r^{-2} \right)^s & \hspace{-28mm} \text{by Properties } \eqref{eqn:eta-bound} \text{ and } \eqref{eqn:eta-decay}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{2\alpha}{(C(s))^2} \right)^{s} \cdot \sum_{r = \lceil C(s) \rceil}^\infty \exp\left(-\beta r s\right) & \hspace{-28mm} \text{by \Cref{lem:binomial}}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{2\alpha}{(C(s))^2} \right)^{s} \cdot \frac{1}{1 - e^{-\beta s}} \cdot  \exp\left(-\beta s C(s)\right) & \hspace{-28mm} \text{by \Cref{lem:inv-exp-tail}}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{72\alpha R s}{N^2} \right)^{s} \cdot \frac{2}{\beta} \cdot  \exp\left(-\frac{\beta N}{6\ln R}\right) & \text{by definition of $C(s)$}\\
&\qquad\qquad\text{ and since } \frac{1}{1 - e^{-\beta s}} \le \frac{1}{1 - (1-\beta/2)} = \frac{2}{\beta} \text{ for } s \ge 1, \beta \in (0, 1) \hspace{-10em}&\hspace{-10em} \\
&\le 2^{-R}  \sum_{s = T}^{R} 2^{-s} \cdot \exp\left(-\frac{3 \beta \sqrt{\alpha} R }{ \ln R} + \ln(2/\beta)\right)&\hspace{-28mm}\text{setting } N = \lceil 20 \sqrt{\alpha}\rceil R \\
&\le 2^{-R} \cdot (2 N R)^{-2\Delta},
\end{align*}
where
\[\Delta = \frac{1}{2\ln(2NR)} \cdot \left(\frac{3\beta \sqrt{\alpha} R}{\ln R} - \ln(2/\beta) \right) \ge \frac{\beta \sqrt{\alpha} R}{4\ln^2 R}\]
holds for sufficiently large $R$ by the restrictions placed on $\alpha$ and $\beta$ in the statement of the lemma.
\end{proof}

