\begin{lemma} \label{lem:ughcor}
Let $\delta > 0$, $\gamma > 2\delta$, and let $$G=\{x_1, \dots, x_R \in \{-1,1\}^{N \cdot R} \colon (\mathsf{ OR}_N(x_1), \dots, \mathsf{ OR}_N(x_R)) \in
H_{\leq \gamma \cdot R}^R \cup \{\mathbf{-1}\}\}.$$
Define $\Phi : \{-1,1\}^R \to \{-1,1\}$ by $\Phi(-\mathbf{1}) = -1/2$, $\Phi(\mathbf{1}) = 1/2$ and $\Phi(z) = 0$ otherwise. Let $\psi : \{-1,1\}^N \to \{-1,1\}$ be any dual witness for $\mathsf{ OR}_N$ such that $\|\psi\|_1 = 1$, $\langle \psi, \mathbf{1}\rangle = 0$, and $\langle \psi, \mathsf{ OR}_N \rangle \ge 1 - \delta$. Then
\[\sum_{x \in G}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{GapAND}_{R}^{\gamma} \circ \mathsf{ OR}_N\right)(x) - \sum_{x \in\{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)|
\geq 1-\delta^R -\exp(-(\gamma - \delta) R/3).\]
\end{lemma}

The proof of \Cref{lem:ughcor} crucially relies on a special property, called \emph{one-sided error}, that is satisfied by any dual polynomial for $\mathsf{ OR}$.

\begin{definition}
Let $f : \{-1,1\}^N \to \{-1,1\}$ and let $\psi : \{-1,1\}^N \to \mathbb{R}$. We say that $\psi$ has one-sided error with respect to $f$ if for all $x \in \{-1,1\}^N$,
\begin{equation}
f(x) = 1 \implies \psi(x) > 0.
\end{equation}
\end{definition}
The following lemma shows that \emph{any} dual witness for the $\mathsf{ OR}_N$ function has one-sided error.

\begin{lemma}[Gavinsky and Sherstov \cite{comm2}] \label{lem:gs}
Let $\psi : \{-1,1\}^N \to \mathbb{R}$ be a function with pure high degree at least $1$ such that $\langle \psi, \mathsf{ OR}_N \rangle > 0$. Then $\psi$ has one-sided error with respect to $\mathsf{ OR}_N$.
\end{lemma}


In particular, if $\psi$ is such a dual witness for $\mathsf{ OR}_N$, then we have
\begin{equation} \label{eqn:mybullshitequation}
\sum_{x \in A_{+1}} |\psi(x)| \le \frac{1}{2}(1 - \langle \psi, \mathsf{ OR}_N \rangle), \qquad \sum_{x \in A_{-1}} |\psi(x)| = 0,
\end{equation}
where the sets $A_{+1}$ and $A_{-1}$ are, respectively, the sets of false positive and false negative errors given by
\begin{align*}
&A_{+1} = E_+(\psi, \mathsf{ OR}_N) = \{x \in \{-1,1\}^N : \psi(x) > 0,  \mathsf{ OR}_N(x) = -1\}, \\
&A_{-1} = E_-(\psi, \mathsf{ OR}_N) = \{x \in \{-1,1\}^N : \psi(x) < 0, \mathsf{ OR}_N(x) = +1\}.
\end{align*}




\begin{proof}[Proof of \Cref{lem:ughcor}]
We begin by observing that the quantity of interest can be written as
\begin{align}
&\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - \nonumber \\
&\qquad\qquad \left( \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) + \sum_{x \in\{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)| \right) \nonumber \\
\ge &\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - 2 \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)|. \label{eqn:buttz}
\end{align}
We estimate each term of Expression~\eqref{eqn:buttz} separately, beginning with the first term. Just as in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we have
\begin{align*}
\sum_{x \in \{-1,1\}^{N \cdot R}} (\Phi \star \psi)(x) \cdot (\mathsf{AND}_R \circ \mathsf{ OR}_N)(x) &= \sum_{z \in \{-1,1\}^R} \Phi(z) \cdot \mathbb{E}_y[\mathsf{AND}_R(\dots, y_i z_i, \dots)]
\end{align*}
where $y \in \{-1,1\}^R$ is a random string whose $i$th bit independently takes the value $-1$ with probability $2 \sum_{x \in A_{z_i}} |\psi(x)|$. For $z = -\mathbf{1}$, we have by~\eqref{eqn:mybullshitequation} that $2 \sum_{x \in A_{-1}} |\psi(x)| = 0$, so the contribution of the corresponding term to the sum is $1/2$. For $z = \mathbf{1}$, we use the fact that $2 \sum_{x \in A_{+1}} |\psi(x)| \le \delta$ to compute
\begin{align*}
\frac{1}{2} \cdot \mathbb{E}_{y}[\mathsf{AND}_R(\dots, y_i, \dots)] &= \frac{1}{2} \cdot \left(1 - 2\Pr_y[\mathsf{AND}_R(\dots, y_i, \dots) = -1 ] \right) \\
&\ge \frac{1}{2} \cdot \left(1 - 2\delta^R\right).
\end{align*}
Hence, the first summand of~\eqref{eqn:buttz} is at least $1-\delta^R$.

We now estimate the second summand, $2 \sum_{x \notin G} |(\Phi \star \psi)(x)|$. As in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we let $\lambda$ denote the distribution with probability mass function $\lambda(x) = |\psi(x)|$. Then
\begin{align*}\hspace{-2.2em}
2\sum_{x \notin G} |(\Phi \star \psi)(x)| &= 2^{R+1} \mathbb{E}_{\lambda^{\otimes R}} [|\Phi(\dots, \operatorname{sgn} \psi(x_i), \dots)| \cdot \mathbb{I}(x \notin G)] \\
&= 2\sum_{z \in \{-1,1\}^R} |\Phi(z)| \cdot \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = z] \\
&= \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{-1}] + \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}].
\end{align*}
We analyze each term of this sum separately. For the first term, observe that by one-sided error of $\psi$, it follows that if $x = (x_1, \dots, x_R)$ is any input $\operatorname{sgn}(\psi(x_i)) = -1$ for all $i$ then $\mathsf{ OR}_N(x_i) = -1$ for all $i$. Thus we are guaranteed that $x \in G$, so the contribution of the first summand is zero. To analyze the second summand, let us denote by $r_i \in \{0, 1\}$ the indicator random variable for the event $\mathsf{ OR}_N(x_i) = -1$ when $x_i$ is drawn from the conditional distribution $(\lambda | \operatorname{sgn}(\psi(x_i)) = 1)$. Then
\begin{align*}
\Pr[r_i = 1] &= \Pr_{x_i \sim \lambda}[\mathsf{ OR}_N(x_i) = -1 | \operatorname{sgn}(\psi(x_i)) = 1] \\
&= 2\sum_{x \in A_{+1}} |\psi(x_i)| \\
&\le \delta
\end{align*}
by~\eqref{eqn:mybullshitequation}. Hence,
\begin{align*}
 \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}] &\le \Pr\left[ \sum_{i = 1}^R r_i  > \gamma R\right] \\
 &\le \exp\left(-\frac{(\gamma - \delta)R}{3}\right)
\end{align*}
by the multiplicative Chernoff bound.\footnote{The formulation we use here is as follows. Let $r_1, \dots, r_R$ be independent $\{0, 1\}$-valued random variables, $S = \sum_{i=1}^R r_i$, and $\mu = \mathbb{E}[S]$. Then for $\eta > 1$, we have $\Pr[S > (1+\eta) \mu] \le \exp(-\eta \mu / 3)$. In this application, we are taking $\mu \le \delta R$ and $\eta = \gamma R / \mu - 1 > 1$.} Thus, we have
\[2 \sum_{x \notin G} |(\Phi \star \psi)(x)| \le \exp\left(-\frac{(\gamma - \delta)R}{3}\right).\]
Putting everything together, we see that Expression~\eqref{eqn:buttz} is at least $1 - \delta^R - \exp\left(-(\gamma - \delta) R / 3\right)$ as we wanted to show.
\end{proof}

\@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{$k$-distinctness.} In this problem, we are given $N$ numbers in $[R]$ and must decide if any range item appears at least $k$ times in the list (i.e., is there an $i\in [R]$ with $f_i \geq k$?). This generalizes the well-studied Element Distinctness problem, which is the same as $2$-distinctness.

Ambainis~\cite{ambainis} first used quantum walks to give an $O(n^{k/(k+1)})$ upper bound on the quantum query complexity of any problem with certificates of size $k$, including $k$-distinctness and $k$-sum.\footnote{In the $k$-sum problem, we are given $N$ numbers in $[R]$ and asked to decide if any $k$ of them sum to $0 \pmod R$.}
Later, Belovs introduced a beautiful new framework for designing quantum algorithms~\cite{belovsframework} and used it to improve the upper bound for $k$-distinctness to $O(n^{3/4-1/(2^{k + 2} - 4)})$ \cite{belovs}. 
Several subsequent works have used Belovs' $k$-distinctness algorithm as a black-box subroutine for solving more complicated problems (e.g., \cite{entropy, montanaro}).

As for lower bounds, Aaronson and Shi \cite{aaronsonshi} established an $\tilde{\Omega}(n^{2/3})$ lower bound on the approximate degree of $k$-distinctness for any $k\geq 2$. Belovs and \v{S}palek used the adversary method to prove a lower bound of $\Omega(n^{k/(k+1)})$ on the quantum query
complexity of $k$-sum, showing that Ambainis' algorithm is tight for $k$-sum. 
They asked whether their techniques can prove an $\omega(n^{2/3})$ quantum query lower bound for $k$-distinctness. 
We achieve this goal, but using the polynomial method instead of the adversary method.
Our main result is the following:

This is nearly tight for large $k$, as it approaches Belovs' upper bound of $O(n^{3/4-1/(2^{k + 2} - 4)})$. 
Note that both bounds approach $\Theta(n^{3/4})$ as $k\to \infty$.
It remains an intriguing open question to close the gap between $n^{3/4-1/(2^{k + 2} - 4)}$ and $n^{3/4-1/(2k)}$, especially for small values of $k \geq 3$. 

Our $k$-distinctness lower bound also implies an $\tilde{\Omega}(n^{3/4-1/(2k)})$ lower bound on the quantum query complexity of approximating the maximum frequency, $F_{\infty}$, of any element up to relative error less than $1/k$ \cite{montanaro}, improving over the previous best bound of $\tilde{\Omega}(n^{2/3})$. 



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{Image Size Testing.} In this problem, we are given $N$ numbers in $[R]$ and $0<\gamma<1$, and must decide if every range item appears at least once or if at most $\gamma\cdot R$ range items appear at least once. 
We show for any $\gamma > 0$, the problem has approximate degree and quantum query complexity $\tilde{\Omega}(\sqrt{n})$. 
This holds as long as $N=c\cdot R$ for a certain constant $c>0$.

This lower bound is tight, matching a quantum algorithm of Ambainis, Belovs, Regev, and de Wolf \cite{juntatesting}, and resolves a conjecture from their work. The previous best lower bound was $\Omega(n^{1/3})$ \cite{juntatesting} obtained via reduction to the Collision lower bound \cite{aaronsonshi}. The classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}.

The version of image size testing we define is actually a special case of the one studied in \cite{juntatesting}. The version we define is solvable via the following simple algorithm making $O(\sqrt{n})$ queries: pick a random range item, and Grover search for an instance of that range item.  The fact that our lower bound holds even for this special case of the problem considered in prior works obviously only makes our lower bound stronger.

This lower bound also serves as a starting point to establish the next three lower bounds.



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{$k$-junta Testing.} In this problem, we are given the truth table of a Boolean function and have to determine if the function depends on at most $k$ variables or if it is $\epsilon$-far from any such function. 

The best classical algorithm for this problem uses $O(k \log k+k/\varepsilon)$ queries~\cite{Bla09}. The problem was first studied in the quantum setting by  At{\i}c{\i} and Servedio \cite{roccoquantum}, who gave a quantum algorithm making $O(k/\varepsilon)$ queries. This was later improved by Ambainis et al.~\cite{juntatesting} to $\tilde{O}(\sqrt{k/\varepsilon})$. They also proved a lower bound of $\Omega(k^{1/3})$. 
Via a connection established by Ambainis et al., our image size testing lower bound implies a $\tilde{\Omega}(\sqrt{k})$ lower bound on the approximate degree and quantum query complexity of $k$-junta testing (for some $\varepsilon=\Omega(1)$).

This matches the upper bound of~\cite{juntatesting}, resolving the main open question from their work. 



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{Statistical Distance From Uniform $(\mathsf{ SDU})$.} In this problem, we are given $N$ numbers in $[R]$, which we interpret 
as a probability distribution $p$, where $p_i=f_i/N$, the fraction of times $i$ appears.
The goal is to compute the statistical distance between $p$ and the uniform distribution to error $\varepsilon$.

This problem was studied by Bravyi, Harrow, and Hassidim \cite{bravyi}, who gave an $O(\sqrt{n})$-query quantum algorithm approximating the statistical distance between
 two input distributions to additive error $\varepsilon=\Omega(1)$.
We show that the approximate degree and quantum query complexity of this task are $\tilde{\Omega}(\sqrt{n})$, even when one of the distributions is known to be the uniform distribution.

This matches the upper bound of Bravyi et al.~\cite{bravyi} and answers the main question left open from that work. Note that the classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}.



