  {\normalfont\normalsize\bfseries}
{Entropy Approximation.} As in the previous problem, we interpret the input as a probability distribution, and the goal is to compute its Shannon entropy to additive error $\varepsilon$. The classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}. We show that, for some $\varepsilon=\Omega(1)$,  the approximate degree and quantum query complexity are $\tilde{\Omega}(\sqrt{n})$.

\begin{definition}
For integers $k, N$ with $k \le N$, define the function $\mathsf{THR}^k_N : \{-1,1\}^N \to \{-1,1\}$ by $\mathsf{THR}^k_N(x) = -1$ iff $|x| \ge k$.
\end{definition}


If we let $f = \mathsf{ OR}_R$ and $g = \mathsf{THR}_N^k$, then the function $F^{\operatorname{prop}}$ is the dummy augmented $k$-distinctness function $\mathsf{dDIST}_{N, R}^k$.

\begin{proof}
 Recall that $\psi(x) = \omega(|x|) / \binom{N}{|x|}$ where $\omega \colon [M]_{0} \to \mathbb{R}$. By Equation~\eqref{eqn:omega-balanced} we may write $\omega = \omega_{+1} - \omega_{-1}$  where $\omega_{+1}$ and $\omega_{-1}$ are non-negative
functions satisfying
\begin{equation} \label{eq:sweeteq} \sum_{t=0}^k \omega_{+1}(t) = \sum_{t=0}^k \omega_{-1}(t) = 1/2.\end{equation}



By the definition of dual block composition, we have
\[(\Phi \star \psi)(x_1, \dots, x_R) = 2^R \cdot \Phi(\dots, \operatorname{sgn}\left(\psi(x_i)\right), \dots) \cdot \prod_{i = 1}^R |\psi(x_i)|.\]
Consequently,
\begin{align}
\notag \sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| &= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{\substack{(x_1, \dots, x_R) \notin  H_{\le N}^{N \cdot R} \text{ s.t.} \\ \notag \operatorname{sgn}\left( \psi(x_1)\right) = z_1, \dots, \operatorname{sgn}\left(\psi(x_R)\right) = z_R}} \prod_{i = 1}^R |\psi(x_i)| \right) \\
&= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(x_1, \dots, x_R) \notin H_{\le N}^{N \cdot R}} \prod_{i = 1}^R \frac{\omega_{z_i}(|x_i|)}{\binom{N}{ |x_i|}} \right). \label{finallineman}
\end{align}

Observe that for any $(t_1, \dots, t_R) \in [M]_0^R$, the number of inputs $(x_1, \dots, x_R) \in \left(\{-1,1\}^N\right)^R$
such that $|x_i| = t_i$ for all $i \in [R]$ is exactly $\prod_{i=1}^{R} \binom{N}{ t_i}$. 
Hence, defining $$P = \{(t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\},$$ we
may rewrite Expression
\eqref{finallineman} as
\[2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(t_1, \dots, t_R) \in P} \prod_{i = 1}^R \omega_{z_i}(t_i) \right).\]
To control this quantity, we appeal to the following combinatorial lemma,
