\begin{lemma} \label{lem:inv-exp-tail}
Let $m \in \mathbb{N}$ and $\eta > 0$. Then
\[\sum_{r = m}^\infty e^{-\eta r} = \frac{1}{1 - e^{-\eta}} \cdot e^{-\eta m}.\]
\end{lemma}

\begin{proof}
We calculate
\[\sum_{r = m}^\infty e^{-\eta r} = e^{-\eta m}  \cdot \sum_{r = 0}^\infty e^{-\eta r} = e^{-\eta m} \cdot \frac{1}{1 - e^{-\eta}}.\qedhere
\]
\end{proof}




\begin{lemma} \label{lem:inv-sqrt}
Let $m \in N$. Then
\[\sum_{r = 1}^m \frac{1}{\sqrt{r}} \le 2 \sqrt{m}.\]
\end{lemma}

\begin{proof}
Using the fact that the function $1/\sqrt{t}$ is decreasing, we may estimate
\[
  \sum_{r = 1}^m \frac{1}{\sqrt{r}} \le \int_{0}^m \frac{1}{\sqrt{t}} \ dt = 2\sqrt{m}.\qedhere
\]
\end{proof}

\begin{proof}

Let $T = \lfloor \frac{N}{2M} \rfloor$.  For each $s \in \{T, \dots, R\}$, let 
\[C(s) = \max \left\{ \frac{N}{6 s \ln R}, \frac{N}{6\sqrt{R \cdot s}} \right\}.\]

We begin with a simple, but important, structural observation about the set $P$. Let $t = (t_1, \dots, t_R) \in [M]_0^R$ be a sequence such that $t_1 + \dots + t_R > N$. Then  we claim that there exists an $s \in \{T \dots, R\}$ such that $t_i \ge C(s)$ for at least $s$ indices $i \in [R]$. To see this, assume without loss of generality that the entries of $\vec{t}$ are sorted so that $t_1 \ge t_2 \ge \dots \ge t_R$. Then there must exist an $s \geq T$ such that $t_s \ge C(s)$. Otherwise, because no $t_i$ can exceed $M$, we would have:
\begin{align*}
t_1 + \dots + t_R  &< T \cdot M + \sum_{s = 1}^R C(s) \\
&\le \frac{N}{2} + \frac{N}{6 \ln R} \sum_{s = 1}^{\lfloor R / \ln^2 R \rfloor} \frac{1}{s} + \frac{N}{6\sqrt{R}} \sum_{s = \lceil R / \ln^2 R \rceil}^R \frac{1}{\sqrt{s}}\\
&\le \frac{N}{2}+ \frac{N}{6} + \frac{N}{3} \\
&= N.
\end{align*}
where the last inequality follows from \Cref{lem:inv-sqrt} and the fact that $\sum_{s = 1}^m s^{-1} \le \ln m + 1$ (and $R$ is sufficiently large). 
Since the entries of $\vec{t}$ are sorted, the preceding values $t_1, \dots, t_{s-1} \geq C(s)$ as well. 



For each subset $S \subseteq [R]$, define
\[P_S = \{\vec{t} \in P : t_i \ge C(|S|)\text{ for all indices }i \in S\}.\]
The observations above guarantee that for every $\vec{t}=(t_1, \dots, t_R) \in P$, 
there exists some set $S$ of size at least $s \in \{T, \dots, R\}$ such that 
$t_i \geq C(s)$ for all $i \in S$. Hence
\begin{align*} \hspace{-10mm}
\sum_{\vec{t} \in P} \prod_{i = 1}^R \eta_i(t_i)  & \leq \sum_{s = T}^{R} \sum_{S \subseteq [R] : |S| = s} \sum_{\vec{t} \in P_S} \prod_{i = 1}^R \eta_i(t_i) \\
& \leq \sum_{s = T}^{R} \binom{R}{s} \left( \max_{i \in \{1, \dots, R\}} \left( \sum_{r=\lceil C(s) \rceil}^M \eta_i(r)\right) \right)^s  \left( \max_{i \in \{1, \dots, R\}} \left( \sum_{r = 0}^M \eta_i(r) \right)\right)^{R-s} \hspace{-3.3em}&\hspace{-3em}\\
&\leq  2^{-R}\sum_{s = T}^{R} \binom{R}{s} \left( \sum_{r = \lceil C(s) \rceil}^M 2\alpha \exp(-\beta r ) r^{-2} \right)^s & \hspace{-28mm} \text{by Properties } \eqref{eqn:eta-bound} \text{ and } \eqref{eqn:eta-decay}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{2\alpha}{(C(s))^2} \right)^{s} \cdot \sum_{r = \lceil C(s) \rceil}^\infty \exp\left(-\beta r s\right) & \hspace{-28mm} \text{by \Cref{lem:binomial}}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{2\alpha}{(C(s))^2} \right)^{s} \cdot \frac{1}{1 - e^{-\beta s}} \cdot  \exp\left(-\beta s C(s)\right) & \hspace{-28mm} \text{by \Cref{lem:inv-exp-tail}}\\
&\le 2^{-R} \sum_{s = T}^{R} \left( \frac{Re}{s} \right)^s \left(\frac{72\alpha R s}{N^2} \right)^{s} \cdot \frac{2}{\beta} \cdot  \exp\left(-\frac{\beta N}{6\ln R}\right) & \text{by definition of $C(s)$}\\
&\qquad\qquad\text{ and since } \frac{1}{1 - e^{-\beta s}} \le \frac{1}{1 - (1-\beta/2)} = \frac{2}{\beta} \text{ for } s \ge 1, \beta \in (0, 1) \hspace{-10em}&\hspace{-10em} \\
&\le 2^{-R}  \sum_{s = T}^{R} 2^{-s} \cdot \exp\left(-\frac{3 \beta \sqrt{\alpha} R }{ \ln R} + \ln(2/\beta)\right)&\hspace{-28mm}\text{setting } N = \lceil 20 \sqrt{\alpha}\rceil R \\
&\le 2^{-R} \cdot (2 N R)^{-2\Delta},
\end{align*}
where
\[\Delta = \frac{1}{2\ln(2NR)} \cdot \left(\frac{3\beta \sqrt{\alpha} R}{\ln R} - \ln(2/\beta) \right) \ge \frac{\beta \sqrt{\alpha} R}{4\ln^2 R}\]
holds for sufficiently large $R$ by the restrictions placed on $\alpha$ and $\beta$ in the statement of the lemma.
\end{proof}

}
\label{sec:gap-and-corr}


\begin{lemma} \label{lem:ughcor}
Let $\delta > 0$, $\gamma > 2\delta$, and let $$G=\{x_1, \dots, x_R \in \{-1,1\}^{N \cdot R} \colon (\mathsf{ OR}_N(x_1), \dots, \mathsf{ OR}_N(x_R)) \in
H_{\leq \gamma \cdot R}^R \cup \{\mathbf{-1}\}\}.$$
Define $\Phi : \{-1,1\}^R \to \{-1,1\}$ by $\Phi(-\mathbf{1}) = -1/2$, $\Phi(\mathbf{1}) = 1/2$ and $\Phi(z) = 0$ otherwise. Let $\psi : \{-1,1\}^N \to \{-1,1\}$ be any dual witness for $\mathsf{ OR}_N$ such that $\|\psi\|_1 = 1$, $\langle \psi, \mathbf{1}\rangle = 0$, and $\langle \psi, \mathsf{ OR}_N \rangle \ge 1 - \delta$. Then
\[\sum_{x \in G}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{GapAND}_{R}^{\gamma} \circ \mathsf{ OR}_N\right)(x) - \sum_{x \in\{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)|
\geq 1-\delta^R -\exp(-(\gamma - \delta) R/3).\]
\end{lemma}

The proof of \Cref{lem:ughcor} crucially relies on a special property, called \emph{one-sided error}, that is satisfied by any dual polynomial for $\mathsf{ OR}$.

\begin{definition}
Let $f : \{-1,1\}^N \to \{-1,1\}$ and let $\psi : \{-1,1\}^N \to \mathbb{R}$. We say that $\psi$ has one-sided error with respect to $f$ if for all $x \in \{-1,1\}^N$,
\begin{equation}
f(x) = 1 \implies \psi(x) > 0.
\end{equation}
\end{definition}
The following lemma shows that \emph{any} dual witness for the $\mathsf{ OR}_N$ function has one-sided error.

\begin{lemma}[Gavinsky and Sherstov \cite{comm2}] \label{lem:gs}
Let $\psi : \{-1,1\}^N \to \mathbb{R}$ be a function with pure high degree at least $1$ such that $\langle \psi, \mathsf{ OR}_N \rangle > 0$. Then $\psi$ has one-sided error with respect to $\mathsf{ OR}_N$.
\end{lemma}


In particular, if $\psi$ is such a dual witness for $\mathsf{ OR}_N$, then we have
\begin{equation} \label{eqn:mybullshitequation}
\sum_{x \in A_{+1}} |\psi(x)| \le \frac{1}{2}(1 - \langle \psi, \mathsf{ OR}_N \rangle), \qquad \sum_{x \in A_{-1}} |\psi(x)| = 0,
\end{equation}
where the sets $A_{+1}$ and $A_{-1}$ are, respectively, the sets of false positive and false negative errors given by
\begin{align*}
&A_{+1} = E_+(\psi, \mathsf{ OR}_N) = \{x \in \{-1,1\}^N : \psi(x) > 0,  \mathsf{ OR}_N(x) = -1\}, \\
&A_{-1} = E_-(\psi, \mathsf{ OR}_N) = \{x \in \{-1,1\}^N : \psi(x) < 0, \mathsf{ OR}_N(x) = +1\}.
\end{align*}




\begin{proof}[Proof of \Cref{lem:ughcor}]
We begin by observing that the quantity of interest can be written as
\begin{align}
&\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - \nonumber \\
&\qquad\qquad \left( \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) + \sum_{x \in\{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)| \right) \nonumber \\
\ge &\sum_{x \in \{-1,1\}^{N \cdot R}}  ( \Phi \star \psi)(x) \cdot \left(\mathsf{AND}_R \circ \mathsf{ OR}_N\right)(x) - 2 \sum_{x \in \{-1,1\}^{N \cdot R} \setminus G} |(\Phi \star \psi)(x)|. \label{eqn:buttz}
\end{align}
We estimate each term of Expression~\eqref{eqn:buttz} separately, beginning with the first term. Just as in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we have
\begin{align*}
\sum_{x \in \{-1,1\}^{N \cdot R}} (\Phi \star \psi)(x) \cdot (\mathsf{AND}_R \circ \mathsf{ OR}_N)(x) &= \sum_{z \in \{-1,1\}^R} \Phi(z) \cdot \mathbb{E}_y[\mathsf{AND}_R(\dots, y_i z_i, \dots)]
\end{align*}
where $y \in \{-1,1\}^R$ is a random string whose $i$th bit independently takes the value $-1$ with probability $2 \sum_{x \in A_{z_i}} |\psi(x)|$. For $z = -\mathbf{1}$, we have by~\eqref{eqn:mybullshitequation} that $2 \sum_{x \in A_{-1}} |\psi(x)| = 0$, so the contribution of the corresponding term to the sum is $1/2$. For $z = \mathbf{1}$, we use the fact that $2 \sum_{x \in A_{+1}} |\psi(x)| \le \delta$ to compute
\begin{align*}
\frac{1}{2} \cdot \mathbb{E}_{y}[\mathsf{AND}_R(\dots, y_i, \dots)] &= \frac{1}{2} \cdot \left(1 - 2\Pr_y[\mathsf{AND}_R(\dots, y_i, \dots) = -1 ] \right) \\
&\ge \frac{1}{2} \cdot \left(1 - 2\delta^R\right).
\end{align*}
Hence, the first summand of~\eqref{eqn:buttz} is at least $1-\delta^R$.

We now estimate the second summand, $2 \sum_{x \notin G} |(\Phi \star \psi)(x)|$. As in the proofs of \Cref{prop:error-amp} and \Cref{prop:degree-amp}, we let $\lambda$ denote the distribution with probability mass function $\lambda(x) = |\psi(x)|$. Then
\begin{align*}\hspace{-2.2em}
2\sum_{x \notin G} |(\Phi \star \psi)(x)| &= 2^{R+1} \mathbb{E}_{\lambda^{\otimes R}} [|\Phi(\dots, \operatorname{sgn} \psi(x_i), \dots)| \cdot \mathbb{I}(x \notin G)] \\
&= 2\sum_{z \in \{-1,1\}^R} |\Phi(z)| \cdot \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = z] \\
&= \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{-1}] + \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}].
\end{align*}
We analyze each term of this sum separately. For the first term, observe that by one-sided error of $\psi$, it follows that if $x = (x_1, \dots, x_R)$ is any input $\operatorname{sgn}(\psi(x_i)) = -1$ for all $i$ then $\mathsf{ OR}_N(x_i) = -1$ for all $i$. Thus we are guaranteed that $x \in G$, so the contribution of the first summand is zero. To analyze the second summand, let us denote by $r_i \in \{0, 1\}$ the indicator random variable for the event $\mathsf{ OR}_N(x_i) = -1$ when $x_i$ is drawn from the conditional distribution $(\lambda | \operatorname{sgn}(\psi(x_i)) = 1)$. Then
\begin{align*}
\Pr[r_i = 1] &= \Pr_{x_i \sim \lambda}[\mathsf{ OR}_N(x_i) = -1 | \operatorname{sgn}(\psi(x_i)) = 1] \\
&= 2\sum_{x \in A_{+1}} |\psi(x_i)| \\
&\le \delta
\end{align*}
by~\eqref{eqn:mybullshitequation}. Hence,
\begin{align*}
 \Pr_{\lambda^{\otimes R}}[x \notin G | (\dots, \operatorname{sgn}(\psi(x_i)), \dots) = \mathbf{1}] &\le \Pr\left[ \sum_{i = 1}^R r_i  > \gamma R\right] \\
 &\le \exp\left(-\frac{(\gamma - \delta)R}{3}\right)
\end{align*}
by the multiplicative Chernoff bound.\footnote{The formulation we use here is as follows. Let $r_1, \dots, r_R$ be independent $\{0, 1\}$-valued random variables, $S = \sum_{i=1}^R r_i$, and $\mu = \mathbb{E}[S]$. Then for $\eta > 1$, we have $\Pr[S > (1+\eta) \mu] \le \exp(-\eta \mu / 3)$. In this application, we are taking $\mu \le \delta R$ and $\eta = \gamma R / \mu - 1 > 1$.} Thus, we have
\[2 \sum_{x \notin G} |(\Phi \star \psi)(x)| \le \exp\left(-\frac{(\gamma - \delta)R}{3}\right).\]
Putting everything together, we see that Expression~\eqref{eqn:buttz} is at least $1 - \delta^R - \exp\left(-(\gamma - \delta) R / 3\right)$ as we wanted to show.
\end{proof}

\@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{$k$-distinctness.} In this problem, we are given $N$ numbers in $[R]$ and must decide if any range item appears at least $k$ times in the list (i.e., is there an $i\in [R]$ with $f_i \geq k$?). This generalizes the well-studied Element Distinctness problem, which is the same as $2$-distinctness.

Ambainis~\cite{ambainis} first used quantum walks to give an $O(n^{k/(k+1)})$ upper bound on the quantum query complexity of any problem with certificates of size $k$, including $k$-distinctness and $k$-sum.\footnote{In the $k$-sum problem, we are given $N$ numbers in $[R]$ and asked to decide if any $k$ of them sum to $0 \pmod R$.}
Later, Belovs introduced a beautiful new framework for designing quantum algorithms~\cite{belovsframework} and used it to improve the upper bound for $k$-distinctness to $O(n^{3/4-1/(2^{k + 2} - 4)})$ \cite{belovs}. 
Several subsequent works have used Belovs' $k$-distinctness algorithm as a black-box subroutine for solving more complicated problems (e.g., \cite{entropy, montanaro}).

As for lower bounds, Aaronson and Shi \cite{aaronsonshi} established an $\tilde{\Omega}(n^{2/3})$ lower bound on the approximate degree of $k$-distinctness for any $k\geq 2$. Belovs and \v{S}palek used the adversary method to prove a lower bound of $\Omega(n^{k/(k+1)})$ on the quantum query
complexity of $k$-sum, showing that Ambainis' algorithm is tight for $k$-sum. 
They asked whether their techniques can prove an $\omega(n^{2/3})$ quantum query lower bound for $k$-distinctness. 
We achieve this goal, but using the polynomial method instead of the adversary method.
Our main result is the following:

This is nearly tight for large $k$, as it approaches Belovs' upper bound of $O(n^{3/4-1/(2^{k + 2} - 4)})$. 
Note that both bounds approach $\Theta(n^{3/4})$ as $k\to \infty$.
It remains an intriguing open question to close the gap between $n^{3/4-1/(2^{k + 2} - 4)}$ and $n^{3/4-1/(2k)}$, especially for small values of $k \geq 3$. 

Our $k$-distinctness lower bound also implies an $\tilde{\Omega}(n^{3/4-1/(2k)})$ lower bound on the quantum query complexity of approximating the maximum frequency, $F_{\infty}$, of any element up to relative error less than $1/k$ \cite{montanaro}, improving over the previous best bound of $\tilde{\Omega}(n^{2/3})$. 



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{Image Size Testing.} In this problem, we are given $N$ numbers in $[R]$ and $0<\gamma<1$, and must decide if every range item appears at least once or if at most $\gamma\cdot R$ range items appear at least once. 
We show for any $\gamma > 0$, the problem has approximate degree and quantum query complexity $\tilde{\Omega}(\sqrt{n})$. 
This holds as long as $N=c\cdot R$ for a certain constant $c>0$.

This lower bound is tight, matching a quantum algorithm of Ambainis, Belovs, Regev, and de Wolf \cite{juntatesting}, and resolves a conjecture from their work. The previous best lower bound was $\Omega(n^{1/3})$ \cite{juntatesting} obtained via reduction to the Collision lower bound \cite{aaronsonshi}. The classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}.

The version of image size testing we define is actually a special case of the one studied in \cite{juntatesting}. The version we define is solvable via the following simple algorithm making $O(\sqrt{n})$ queries: pick a random range item, and Grover search for an instance of that range item.  The fact that our lower bound holds even for this special case of the problem considered in prior works obviously only makes our lower bound stronger.

This lower bound also serves as a starting point to establish the next three lower bounds.



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{$k$-junta Testing.} In this problem, we are given the truth table of a Boolean function and have to determine if the function depends on at most $k$ variables or if it is $\epsilon$-far from any such function. 

The best classical algorithm for this problem uses $O(k \log k+k/\varepsilon)$ queries~\cite{Bla09}. The problem was first studied in the quantum setting by  At{\i}c{\i} and Servedio \cite{roccoquantum}, who gave a quantum algorithm making $O(k/\varepsilon)$ queries. This was later improved by Ambainis et al.~\cite{juntatesting} to $\tilde{O}(\sqrt{k/\varepsilon})$. They also proved a lower bound of $\Omega(k^{1/3})$. 
Via a connection established by Ambainis et al., our image size testing lower bound implies a $\tilde{\Omega}(\sqrt{k})$ lower bound on the approximate degree and quantum query complexity of $k$-junta testing (for some $\varepsilon=\Omega(1)$).

This matches the upper bound of~\cite{juntatesting}, resolving the main open question from their work. 



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{Statistical Distance From Uniform $(\mathsf{ SDU})$.} In this problem, we are given $N$ numbers in $[R]$, which we interpret 
as a probability distribution $p$, where $p_i=f_i/N$, the fraction of times $i$ appears.
The goal is to compute the statistical distance between $p$ and the uniform distribution to error $\varepsilon$.

This problem was studied by Bravyi, Harrow, and Hassidim \cite{bravyi}, who gave an $O(\sqrt{n})$-query quantum algorithm approximating the statistical distance between
 two input distributions to additive error $\varepsilon=\Omega(1)$.
We show that the approximate degree and quantum query complexity of this task are $\tilde{\Omega}(\sqrt{n})$, even when one of the distributions is known to be the uniform distribution.

This matches the upper bound of Bravyi et al.~\cite{bravyi} and answers the main question left open from that work. Note that the classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}.



  \@startsection{paragraph}{4}
  {\z@}{2ex \@plus 3.3ex \@minus .2ex}{-1em}
  {\normalfont\normalsize\bfseries}
{Entropy Approximation.} As in the previous problem, we interpret the input as a probability distribution, and the goal is to compute its Shannon entropy to additive error $\varepsilon$. The classical query complexity of this problem is $\Theta(n/\log n)$~\cite{VV11}. We show that, for some $\varepsilon=\Omega(1)$,  the approximate degree and quantum query complexity are $\tilde{\Omega}(\sqrt{n})$.

\begin{definition}
For integers $k, N$ with $k \le N$, define the function $\mathsf{THR}^k_N : \{-1,1\}^N \to \{-1,1\}$ by $\mathsf{THR}^k_N(x) = -1$ iff $|x| \ge k$.
\end{definition}


If we let $f = \mathsf{ OR}_R$ and $g = \mathsf{THR}_N^k$, then the function $F^{\operatorname{prop}}$ is the dummy augmented $k$-distinctness function $\mathsf{dDIST}_{N, R}^k$.

\begin{proof}
 Recall that $\psi(x) = \omega(|x|) / \binom{N}{|x|}$ where $\omega \colon [M]_{0} \to \mathbb{R}$. By Equation~\eqref{eqn:omega-balanced} we may write $\omega = \omega_{+1} - \omega_{-1}$  where $\omega_{+1}$ and $\omega_{-1}$ are non-negative
functions satisfying
\begin{equation} \label{eq:sweeteq} \sum_{t=0}^k \omega_{+1}(t) = \sum_{t=0}^k \omega_{-1}(t) = 1/2.\end{equation}



By the definition of dual block composition, we have
\[(\Phi \star \psi)(x_1, \dots, x_R) = 2^R \cdot \Phi(\dots, \operatorname{sgn}\left(\psi(x_i)\right), \dots) \cdot \prod_{i = 1}^R |\psi(x_i)|.\]
Consequently,
\begin{align}
\notag \sum_{x \notin H_{\le N}^{N \cdot R}} |(\Phi \star \psi)(x)| &= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{\substack{(x_1, \dots, x_R) \notin  H_{\le N}^{N \cdot R} \text{ s.t.} \\ \notag \operatorname{sgn}\left( \psi(x_1)\right) = z_1, \dots, \operatorname{sgn}\left(\psi(x_R)\right) = z_R}} \prod_{i = 1}^R |\psi(x_i)| \right) \\
&= 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(x_1, \dots, x_R) \notin H_{\le N}^{N \cdot R}} \prod_{i = 1}^R \frac{\omega_{z_i}(|x_i|)}{\binom{N}{ |x_i|}} \right). \label{finallineman}
\end{align}

Observe that for any $(t_1, \dots, t_R) \in [M]_0^R$, the number of inputs $(x_1, \dots, x_R) \in \left(\{-1,1\}^N\right)^R$
such that $|x_i| = t_i$ for all $i \in [R]$ is exactly $\prod_{i=1}^{R} \binom{N}{ t_i}$. 
Hence, defining $$P = \{(t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\},$$ we
may rewrite Expression
\eqref{finallineman} as
\[2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{(t_1, \dots, t_R) \in P} \prod_{i = 1}^R \omega_{z_i}(t_i) \right).\]
To control this quantity, we appeal to the following combinatorial lemma,
whose proof we delay to \Cref{s:proofofcomb} (this lemma
is a substantial refinement of \cite[Lemma 32]{adegsurj}).

\begin{restatable}{lemma}{combinatorial} \label{lem:combinatorial}
Let $\alpha \le R^2$, let $\beta \in (4\ln^2 R/ \sqrt{\alpha} R, 1)$, and let $R$ be sufficiently large. Let $N = \lceil 20 \sqrt{\alpha}\rceil R$. Let $\eta_i :[M]_0 \to \mathbb{R}$, for $i = 1, \dots R$, be a sequence of non-negative functions where for every $i$,
\begin{align}&\sum_{r = 0}^M \eta_i(r) \le 1 / 2     \label{eqn:eta-bound} \\
&\eta_i(r) \le \alpha \exp(-\beta r) / r^2  \qquad \forall r = 1, \dots, M.     \label{eqn:eta-decay} 
\end{align}
Let $P = \{\vec{t} = (t_1, \dots, t_R) \in [M]_0^R : t_1 + \dots + t_R > N\}$. Then
\[\sum_{\vec{t} \in P} \prod_{i = 1}^R  \eta_i(t_i) \le 2^{-R} \cdot (2NR)^{-2\Delta}\]
where $\Delta \ge \beta\sqrt{\alpha} R / 4\ln^2 R$.
\end{restatable}

Observe that the functions $\omega_{z_i}$ satisfy Condition \eqref{eqn:eta-bound} (cf. Equation \eqref{eq:sweeteq}) and Condition \eqref{eqn:eta-decay} (cf. Property~\eqref{eqn:omega-decay}). We complete the proof by bounding
\begin{align*}
2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \left( \sum_{\vec{t} \in P} \prod_{i = 1}^R \omega_{z_i}(t_i) \right) &\le 2^R \sum_{z \in \{-1,1\}^R} |\Phi(z)| \cdot \left(2^{-R} \cdot (2NR)^{-2\Delta}\right)\\
&=(2NR)^{-2 \Delta} .
\end{align*}
Here, the equality appeals to the condition that $\|\Phi\|_1 = 1$.
\end{proof}


Our final dual witness $\zeta$ is obtained by modifying $\xi = \Phi \star \psi$ to zero out all of the mass it places on inputs of total Hamming weight larger than $N$. The following proposition captures the conditions under which this postprocessing step can be done.

\begin{proof}
To establish property (1), we use the fact that for $\mu > 0$, the value of the degree $d$ Chebyshev polynomial can be written~\cite[\S 3.2 Problem 8(f)]{cheney} 
 as
\begin{align*}
T_d(1 + \mu) &= \cosh ( d \operatorname{arcosh} ( 1 + \mu) ) \\
& \ge \cosh ( d \sqrt{\mu} ) & \text{ for } \mu \le 1\\
& \ge \frac{1}{2} \cdot \exp(d \sqrt{\mu}).
\end{align*}
Property (2) appears as~\cite[3.2 Problem 19]{cheney}.
\end{proof}


We are now ready to establish
the existence of a low-degree polynomial that approximates $\mathsf{ OR}$ at all inputs of low Hamming weight.

\medskip \noindent \textbf{Bounding $p_{\mathcal{R}}$ Outside of $P_{\mathcal{R}}$.}
For an input $x\in [R]^N$ outside of $\mathcal{P}_\mathcal{R}$, let $b_\mathcal{R}(x)$ be the number of range items that appear more than $T$ times, i.e., 
\begin{equation}\label{eq:b}
    b_\mathcal{R}(x) = |\{r\in\mathcal{R}:\operatorname{\#}_r(x)>T\}|.
\end{equation}
We claim that $|p_{\mathcal{R}}(x) | \leq {\exp\left(b_\mathcal{R}(x) \cdot \tilde{O}(\sqrt{T})\right)}$. This bound relies on the following elementary lemma.

\begin{proof}
We prove the lemma by induction on the number of variables $n$. If $n = 0$, then $p$ is a constant in the interval $[0, 1]$ and the claim is true.

Now suppose the claim is true for $n-1$ variables, and let $p : \mathbb{R}^n \to \mathbb{R}$ with $p(x) \in [0, 1]$ for $x \in \{0,1\}^n$. We begin by decomposing
\[p(x) = (1-x_n) \cdot q_0(x_1, \dots, x_{n-1}) + x_n \cdot q_1(x_1, \dots, x_{n-1})\]
where $q_0$ and $q_1$ are themselves multilinear polynomials. Since $p(x) \in [0, 1]$ for all $x \in \{0,1\}^n$, this is in particular true when $x_n = 0$. Hence $q_0(x') \in [0, 1]$ for all $x' \in \{0,1\}^{n-1}$. Similarly, setting $x_n = 1$ reveals that $q_1(x') \in [0, 1]$ for all $x' \in \{0,1\}^{n-1}$. Now for any $x \in \mathbb{R}^n$ with $x' = (x_1, \dots, x_{n-1})$ we have
\begin{align*}
|p(x)| &= \left| (1 - x_n) \cdot q_0(x') + x_n \cdot q_1(x')\right| \\
&\le |1 - x_n| \cdot |q_0(x')| + |x_n| \cdot |q_1(x')| \\
&\le (|1 - x_n| + |x_n|) \cdot \prod_{i = 1}^{n-1} (|1 - x_i| + |x_i|)
\end{align*}
where the final inequality uses the inductive hypothesis. This proves the claim.
\end{proof}

\begin{proof}
To calculate the probability of interest, we begin by analyzing a simplified experiment. Suppose there are $b$ range items $r_1, \dots, r_b$ each appearing greater than $T$ times in $x$. We compute the probability that \emph{none} of the items $r_1, \dots, r_b$ appear in the sample $x_\mathcal{S}$. If $T \ge N - S$, then this probability is zero. Otherwise, by direct calculation, we have for each $i = 1, \dots, b$:
\[\Pr_{\mathcal{S}}[r_i \notin x_\mathcal{S} | r_1 \notin x_\mathcal{S}, \dots, r_{i-1} \notin x_\mathcal{S}] \le \prod_{j = 0}^{S-1} \left(1 - \frac{T}{N-j} \right) \le \left( 1 - \frac{T}{N}\right)^S \le \exp \left(-\frac{ST}{N} \right).\]
Hence the probability that none of $r_1, \dots, r_b$ appear is
\[\Pr_{\mathcal{S}}[r_1 \notin x_\mathcal{S} \land \dots \land r_b \notin x_\mathcal{S}] = \prod_{i  = 1}^b \Pr_{\mathcal{S}}[r_i \notin x_\mathcal{S} | r_1 \notin x_\mathcal{S}, \dots, r_{i-1} \notin x_\mathcal{S}] \le \exp \left(-\frac{bST}{N} \right).\]

Now fix an arbitrary $x$, and let $r_1, \dots, r_{k}$ be the range items appearing greater than $T$ times in $x$. Observe that $k \le N/T$. We estimate the probability of interest by taking a union bound over all subsets of $r_1, \dots, r_k$ of size $b$:
\begin{align*}
\Pr_{\mathcal{S}}[b_{\mathcal{R}(x_\mathcal{S})}(x) \ge b] &\le \sum_{Y \subseteq [k] : |Y| = b} \Pr_{\mathcal{S}}[r_{i_j} \notin x_\mathcal{S} \quad \forall j \in Y] \\
& \le \binom{k}{b} \exp \left(-\frac{bST}{N}\right) \\
&\le \exp \left( -\frac{bST}{N} + b \log N\right).
\end{align*}
\end{proof}


From \Cref{lem:prob-b} we know that $\Pr_{\mathcal{S}}[b_{\mathcal{R}(x_\mathcal{S})}(x)=b] \leq {\exp(-b \cdot \tilde{\Omega}(ST/N))}$.
Hence the $b\geq1$ term \eqref{eq:t2} is at most
\begin{align}
    \sum_{b=1}^{N/T} {\exp(-b \cdot \tilde{\Omega}(ST/N))} \cdot {\exp(b \cdot \tilde{O}(\sqrt{T}))} = o(1),
\end{align}
by choosing $T = \tilde{\Theta}(\sqrt{N})$ and $S = \tilde{\Theta}(N^{3/4})$ appropriately. This shows that the term in \eqref{eq:t2} does not significantly influence the value of the polynomial for any input $x$.

Thus we have for any input $x$,
\begin{align}
    r(x) = \frac{1}{\binom{N}{S}} \sum_{\mathcal{S} \in \binom{[N]}{S}} {\mathds{1}}[b_{\mathcal{R}(x_\mathcal{S})}(x)=0]  \cdot p_{\mathcal{R}(x_\mathcal{S})}(x) + o(1).
\end{align}

By \Cref{lem:promiseSURJ}, we know that if $b_{\mathcal{R}(x_\mathcal{S})}(x)=0$ (and hence $x \in \mathcal{P}_{\mathcal{R}(x_\mathcal{S})}$), then $p_{\mathcal{R}(x_\mathcal{S})}(x) $ is a $(1/10)$-approximation to $\mathsf{ SURJ}(x)$. Applying \Cref{lem:prob-b} once again shows that $\Pr_{\mathcal{S}}[b_{\mathcal{R}(x_\mathcal{S})}(x) \ge 1] \le \exp(- \tilde{\Omega}(N^{1/4}))$, so $\Pr_{\mathcal{S}}[b_{\mathcal{R}(x_\mathcal{S})}(x) = 0] = 1 - o(1)$. 
Hence, for all $x \in [R]^N$, $|r(x) - \mathsf{ SURJ}(x)| \le 1/10 + o(1) \le 1/3$. 

This completes
the proof of \Cref{thm:upper}.

\begin{proof}
Using the construction of \Cref{prop:error-amp} with $m = N$, $M = 4^k$, and $f = \mathsf{THR}_N^k$, we first obtain a function $\varphi : \{-1,1\}^{4^k} \to \mathbb{R}$ with $\|\varphi\|_1 = 1$ and pure high degree $1$ such that
\begin{align*}
&\sum_{x \in E_+(\varphi \star \psi, \mathsf{ OR}_{4^k} \circ \mathsf{THR}^k_N)} |(\varphi \star \psi)(x)| \le \frac{4^k}{48 N} \\
&\sum_{x \in E_-(\varphi \star \psi, \mathsf{ OR}_{4^k} \circ \mathsf{THR}^k_N)} |(\varphi \star \psi)(x)| \le \frac{1}{2} \cdot \left(1 - 4 \cdot 4^{-k} \right)^{4^k} \le \frac{e^{-4}}{2}.
\end{align*}
Now by the construction of \Cref{prop:degree-amp} with $m = 4^k \cdot N$, $M = R/4^{k}$ and $f = \mathsf{ OR}_{4^k} \circ \mathsf{THR}_N^k$, there exists a function $\rho : \{-1,1\}^{R / 4^k} \to \mathbb{R}$ with $\|\rho\|_1 = 1$ and pure high degree $\Omega(2^{-k}\sqrt{R})$ such that
\[ \langle \rho \star (\varphi \star \psi), \mathsf{ OR}_{R/4^k} \circ (\mathsf{ OR}_{4^k} \circ \mathsf{THR}^k_N) \rangle \ge \frac{9}{10} - \frac{4R}{48 N} - 2e^{-4} \ge \frac{2}{3}.\]
Let $\Phi : \{-1,1\}^R \to \mathbb{R}$ be the dual block composition $\rho \star \varphi$. Since the dual block composition preserves $\ell_1$-norms (\Cref{prop:ls}, Condition~\eqref{eqn:ls-norm}) and multiplies pure high degrees (\Cref{prop:ls}, Condition~\eqref{eqn:ls-phd}), the function $\Phi$ itself has $\ell_1$-norm $1$ and pure high degree $\Omega(2^{-k} \sqrt{R})$. The claim now follows from the associativity of dual block composition (\Cref{prop:ls}, Condition~\eqref{eqn:ls-assoc}) and the fact that $\mathsf{ OR}_R = \mathsf{ OR}_{R/4^k} \circ \mathsf{ OR}_{4^k}$.
\end{proof}

